window.SET_EXTRA = [{"name": "3회차", "r": "201~562쪽", "questions": [{"p": "202", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "미디어 재현(representation)에 대한 설명으로 옳지 않은 것은?", "o": ["미디어 콘텐츠를 분석할 때는 표면적 메시지보다 텍스트 속에 숨겨진 의미를 찾아내는 것이 중요하다.", "스튜어트 홀은 미디어 재현이 반영(reflection)과 매우 다르며, 재현을 통해 의미를 적극적으로 구축한다고 보았다.", "미디어는 현실을 그대로 복사·반영하며, 재현 연구는 이미지가 얼마나 실제와 같은지를 판정하는 데 초점을 둔다.", "미디어 콘텐츠는 제작 당시의 사회적·문화적 맥락에 따라 다양한 방식으로 재현된다."], "a": 2, "e": "미디어는 현실을 복사·반영하지 않고 선택적으로 재구성·해석한다. 재현 연구는 이미지의 '실제성'보다 그 표현이 대중의 사회적 현실 인식에 미치는 영향과 파급 효과에 초점을 둔다.", "w": ["맞는 설명. 숨겨진 의미를 찾아내는 비판적 이해가 필요하다.", "맞는 설명. 홀은 재현이 이미 주어진 의미의 전달이 아니라 의미의 적극적 구축이라고 보았다.", "틀린 설명(정답). 미디어는 현실을 선택적으로 재구성하며, 재현 연구는 '실제성'보다 사회적 파급 효과에 초점을 둔다.", "맞는 설명. 재현은 제작 당시의 사회·문화적 맥락의 영향을 받는다."]}, {"p": "204-205", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "언론과 미디어 담론에 관한 설명으로 옳은 것은?", "o": ["하버마스는 언론이 광고·기업·정치적 이해관계에 지배되어 공론장이 권력층의 이익에 봉사하게 되는 현상을 '공론장의 재봉건화'라 불렀다.", "담론은 다른 담론과의 상호작용 없이 독자적으로 의미를 형성한다.", "게이트키핑은 메시지의 수가 늘어나고 원형 그대로 전달되는 과정이다.", "미디어 의제는 공중 의제에 영향을 주지 못한다."], "a": 0, "e": "하버마스는 공론장을 공중의 자유롭고 평등한 의사소통의 장으로 정의했고, 그 기능이 상실되는 현상을 '재봉건화'라 했다. 담론은 다른 담론과의 상호작용·갈등 속에서 의미를 형성하며, 게이트키핑은 메시지가 취사선택되어 줄어들고 변형되는 과정이다.", "w": ["옳은 설명(정답). 공론장의 재봉건화(refeudalization)의 의미이다.", "틀린 설명. 담론은 다른 담론과의 상호작용·갈등·대립 속에서 의미를 형성한다.", "틀린 설명. 게이트키핑은 메시지가 취사선택되어 수가 줄고 변형되는 과정이다.", "틀린 설명. 의제설정이론에 따르면 미디어는 미디어 의제를 공중 의제로 전환할 수 있다."]}, {"p": "208", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "선거 보도에서 후보자의 정책이나 이슈보다 후보자 간 경쟁 상황과 여론 조사 결과를 중점적으로 다루는 프레임은?", "o": ["경주마 보도 프레임", "실용적 프레임", "도덕적 프레임", "주제 중심 프레임"], "a": 0, "e": "경주마 보도 프레임(horse-race frame)에 대한 설명이다. 이 밖에 일화 중심 vs 주제 중심, 도덕적 vs 실용적, 갈등 프레임이 대표 사례로 제시된다.", "w": ["정답. 경쟁 상황과 여론 조사 결과를 중심으로 보도하는 것이 경주마 보도 프레임이다.", "오답. 실용적 프레임은 효율성과 현실적 대안에 중점을 둔다.", "오답. 도덕적 프레임은 도덕적 가치와 윤리적 기준을 강조한다.", "오답. 주제 중심 프레임은 이슈의 사회 구조적 원인과 해결책에 중점을 둔다."]}, {"p": "211-212", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "워들과 데략샨의 정보 장애(information disorder) 유형 중 '한 청소년이 감추고 싶은 사실을 악의적으로 온라인에 유포해 사이버 불링을 유발한 경우'에 해당하는 것은?", "o": ["악의적정보(malinformation)", "오정보(misinformation)", "허위정보(disinformation)", "풍자·패러디"], "a": 0, "e": "정보의 사실 여부와 해를 끼치려는 의도로 구분한다. 오정보=부정확하지만 해칠 의도 없음, 허위정보=거짓을 의도적으로 공유해 해를 끼침, 악의적정보=사실 기반 정보를 악의적으로 사용함.", "w": ["정답. 정보 자체는 사실이지만 해를 끼치려 유포했으므로 악의적정보이다.", "오답. 오정보는 부정확한 정보가 해칠 의도 없이 공유되는 경우이다(예: 부정확한 기상 예보).", "오답. 허위정보는 '거짓' 정보를 의도적으로 퍼뜨리는 경우이다(예: 선거 마타도어).", "오답. 풍자·패러디는 워들의 7가지 유형 중 하나일 뿐, 이 사례와 맞지 않는다."]}, {"p": "214-215", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "필터버블과 반향실(에코체임버) 효과에 대한 설명으로 옳은 것은?", "o": ["필터버블은 확증편향을 약화시키는 효과가 있다.", "유튜브 추천 시스템은 '순위 매기기 시스템'만으로 구성된다.", "필터버블은 일라이 파리저가 제시한 개념으로, 사용자가 자신의 관심사와 일치하는 정보에만 노출되는 현상이다.", "반향실 효과는 다양한 의견을 가진 사람들이 열린 공간에서 토론하며 의견이 수렴되는 현상이다."], "a": 2, "e": "파리저(2011)는 필터버블로 사용자가 '정보 비눗방울'에 갇혀 민주주의와 웰빙에 부정적 영향을 받는다고 했다. 반향실 효과는 같은 의견을 공유하는 폐쇄된 그룹에 머물며 다른 관점을 무시·불신하는 현상으로, 둘 다 확증편향을 강화한다. 유튜브 추천은 후보군 생성 시스템과 순위 매기기 시스템으로 구성된다.", "w": ["틀린 설명. 필터버블은 확증편향을 '강화'한다.", "틀린 설명. 후보군 생성 시스템과 순위 매기기 시스템 두 부분으로 구성된다.", "옳은 설명(정답). 파리저의 필터버블 개념이다.", "틀린 설명. 반향실 효과는 폐쇄된 동질 집단에서 다른 관점을 무시·불신하는 현상이다."]}, {"p": "217", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "루이 알튀세르가 제시한 '이데올로기적 국가 기구(ideological state apparatuses)'에 대한 설명으로 옳은 것은?", "o": ["국가가 교육·종교·미디어 등을 통해 '보이지 않는' 방식으로 이데올로기적 지배와 통제를 수행한다는 개념이다.", "국가가 군대·경찰 등 물리적 강제력으로 직접 통제하는 기구를 말한다.", "미디어는 이데올로기적 국가 기구에 포함되지 않는다.", "주류 미디어에서 충분히 다루지 않는 메시지를 다루는 풀뿌리·시민 미디어를 말한다."], "a": 0, "e": "알튀세르는 교육·종교 등 사회적 기구를 통해 국가가 이데올로기로 지배하며, 미디어도 그중 하나로 '정상'으로 인식되는 생각과 행동을 내면화시킨다고 보았다. 주류 미디어가 다루지 않는 메시지를 다루는 것은 '대안 미디어'이다.", "w": ["옳은 설명(정답). 이데올로기적 국가 기구의 정의이다.", "틀린 설명. 물리적 강제력이 아니라 이데올로기를 통한 지배이다.", "틀린 설명. 미디어는 이데올로기적 국가 기구의 하나이다.", "틀린 설명. 이는 '대안 미디어(alternative media)'의 설명이다."]}, {"p": "226", "s": "제2부 2장 범주4 미디어 산업과 책임", "q": "C-P-N-D 미디어 생태계 관점에서 본 미디어 산업의 변화로 옳지 않은 것은?", "o": ["기기: 거실의 TV 등 가전제품 → 컴퓨터·스마트폰·태블릿 등 개인 기기", "콘텐츠: 일방향 콘텐츠 → 양방향 콘텐츠", "플랫폼: 종합 방송국 → OTT·유튜브 등 멀티미디어 플랫폼", "네트워크: 인터넷 기반 디지털 전달 → 전파 송출 방식의 아날로그 전달"], "a": 3, "e": "네트워크는 아날로그 방식인 전파 송출 환경에서 유·무선으로 데이터를 교환하는 디지털 환경으로 변화하였다.", "w": ["맞는 변화. 기기가 데이터 처리용 개인 기기로 다변화했다.", "맞는 변화. 소비자 니즈를 반영하는 양방향 콘텐츠로 변모했다.", "맞는 변화. 플랫폼이 멀티미디어 플랫폼으로 다변화했다.", "틀린 변화(정답). 방향이 반대이다. 아날로그 전파 송출 → 디지털 환경으로 바뀌었다."]}, {"p": "230-231", "s": "제2부 2장 범주4 미디어 산업과 책임", "q": "미디어의 사회적 책임에 대한 설명으로 옳지 않은 것은?", "o": ["책임을 강조해 규제를 지나치게 강화하면 위축효과가 발생해 국민의 알 권리에 부응하지 못할 수 있다.", "미디어의 사회적 책임에는 국가·사회 발전에 긍정적 역할을 해야 한다는 적극적 책임과 영향력을 오남용하지 않는다는 소극적 책임이 있다.", "일반적으로 미디어의 사회적 책임이라 함은 적극적 책임을 뜻한다.", "미디어 기업의 소유집중 배제, 외국자본 참여 제한 같은 법적 규제는 미디어의 사회적 책임을 반영한다."], "a": 2, "e": "일반적으로 미디어의 사회적 책임은 영향력을 오남용하지 않는다는 '소극적 책임'을 뜻한다. 과도한 규제의 위축효과 때문에 윤리강령 제정, 옴부즈만 도입, 신문평의회 설치 같은 자율규제가 논의되었다.", "w": ["맞는 설명. 위축효과(chilling effect)에 대한 우려이다.", "맞는 설명. 적극적 책임과 소극적 책임의 두 측면이 있다.", "틀린 설명(정답). 일반적으로는 '소극적 책임'을 뜻한다.", "맞는 설명. 특수한 지위에서 나오는 영향력에 공적 책무를 지우는 규제이다."]}, {"p": "232-233", "s": "제2부 2장 범주4 미디어 산업과 책임", "q": "미디어에서의 권리침해와 책무성에 대한 설명으로 옳은 것은?", "o": ["맥퀘일은 법적인 책무(liability)만으로 미디어 책무성을 확보해야 한다고 보았다.", "거짓·과장·기만 광고를 금지하는 대표 법률은 「정보통신망법」이다.", "개인정보자기결정권은 자신에 관한 정보가 언제, 누구에게, 어느 범위까지 알려지고 이용될지 정보 주체 스스로 결정할 수 있는 권리이다.", "명예훼손은 허위 사실을 적시한 경우에만 성립하며 사실 적시는 해당하지 않는다."], "a": 2, "e": "명예훼손은 사실 또는 허위 사실을 적시해 외부적 명예를 훼손하는 행위이다. 책무성은 법적 책무(liability)와 자발적 사회적 의무(answerability)로 구분되며, 맥퀘일은 두 가지의 조화로운 적용을 강조했다. 거짓·과장·기만 광고를 금지하는 대표 법률은 「표시·광고의 공정화에 관한 법률」이다.", "w": ["틀린 설명. 맥퀘일은 자발적 사회적 의무와 법적 책무의 조화를 강조했다.", "틀린 설명. 대표 법률은 「표시·광고의 공정화에 관한 법률」이다.", "옳은 설명(정답). 개인정보자기결정권의 정의이다.", "틀린 설명. 명예훼손은 사실 또는 허위 사실을 적시하는 경우 모두 해당한다."]}, {"p": "235-236", "s": "제2부 2장 범주4 미디어 산업과 책임", "q": "미디어를 통한 사회 참여와 소셜 협업에 대한 설명으로 옳지 않은 것은?", "o": ["'집단 지성'이라는 용어는 1910년 곤충학자 윌리엄 모턴 휠러가 개미의 사회적 행동을 관찰하며 제시했다.", "소셜 협업은 한 명의 전문가 판단에 의존해 효율을 높이는 것이 핵심 특징이다.", "소셜 미디어는 참여·공유·개방으로 요약되는 플랫폼이다.", "소셜 미디어로 '참여의 효용성'이 커지면서 주류에서 소외되었던 사람들도 의제 설정과 여론 형성에 직접 참여하게 되었다."], "a": 1, "e": "소셜 협업은 소셜 미디어와 온라인 플랫폼으로 소통·공유하며 가치를 공동 창출하는 프로세스로, '집단 지성'을 활용한다는 것이 핵심 특징이다. 이점으로 시간·공간 제약 극복, 비용 절감, 관리 이슈 감소가 있다.", "w": ["맞는 설명. 휠러의 개미 관찰에서 착안한 개념이다.", "틀린 설명(정답). 소셜 협업의 특징은 '집단 지성'을 활용한다는 것이다.", "맞는 설명. 참여(participation), 공유(sharing), 개방(openness)이다.", "맞는 설명. 소셜 미디어의 긍정적 역할이다."]}, {"p": "238", "s": "제2부 2장 범주4 미디어 산업과 책임", "q": "미디어 산업의 '3C 통합 소비(converged consumption)' 트렌드에서 3C에 해당하지 않는 것은?", "o": ["콘텐츠(contents)", "커뮤니티(community)", "커머스(commerce)", "커버리지(coverage)"], "a": 3, "e": "3C는 콘텐츠·커뮤니티·커머스이다. 영상 시청 중 상품을 구매하는 서비스로 확장되며 라이브 커머스로 진화하고 있다.", "w": ["해당함.", "해당함.", "해당함.", "해당하지 않음(정답). 3C는 콘텐츠, 커뮤니티, 커머스이다."]}, {"p": "246", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "우리나라 디지털 권리장전(2023)이 제시한 기본 원칙에 해당하지 않는 것은?", "o": ["디지털에 대한 공정한 접근과 기회의 균등", "자율과 창의 기반의 디지털 혁신의 촉진", "국가 주도의 디지털 콘텐츠 사전 심의 강화", "디지털 환경에서의 자유와 권리 보장"], "a": 2, "e": "5대 기본 원칙은 자유와 권리 보장, 공정한 접근과 기회의 균등, 안전하고 신뢰할 수 있는 디지털 사회, 자율과 창의 기반의 디지털 혁신 촉진, 인류 후생의 증진이다.", "w": ["해당함. 둘째 원칙이다.", "해당함. 넷째 원칙이다.", "해당하지 않음(정답). 나머지 원칙은 '안전하고 신뢰할 수 있는 디지털 사회'와 '인류 후생의 증진'이다.", "해당함. 첫째 원칙이다."]}, {"p": "247-248", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "'잊힐 권리(right to be forgotten)'에 대한 설명으로 옳은 것은?", "o": ["2014년 유럽사법재판소(ECJ) 판결에서 검색 엔진에 자신에 관한 검색 결과 삭제를 요청할 수 있다고 판시하며 처음 인정되었다.", "미국 연방대법원 판결로 처음 인정된 권리이다.", "우리나라의 아동·청소년 지우개 서비스는 40세 미만이면 신청할 수 있다.", "불법으로 게시된 정보만을 대상으로 한다."], "a": 0, "e": "잊힐 권리는 인터넷에 '적법하게' 공개된 개인의 사진·정보에 대해 접근 차단이나 삭제를 요구할 권리로, 검색 배제·금지·차단으로 실현된다. 우리나라는 2023년 4월부터 지우개 서비스를 시범 운영 중이며 30세 미만이 신청할 수 있다.", "w": ["옳은 설명(정답). 2014년 ECJ 판결로 처음 인정되었다.", "틀린 설명. 유럽사법재판소(ECJ) 판결로 인정되었다.", "틀린 설명. 지우개 서비스는 30세 미만이 신청할 수 있다.", "틀린 설명. 인터넷에 '적법하게' 공개된 정보가 대상이다."]}, {"p": "250-251", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "지식재산권에 대한 설명으로 옳은 것은?", "o": ["실용신안권은 고도의 발명을 보호하며 보호 기간은 20년이다.", "상표권은 보호 기간 10년이 지나면 갱신할 수 없다.", "실연자(배우·가수·연주자), 음반 제작자, 방송사업자에게 인정되는 권리를 저작 인접권이라 한다.", "산업재산권은 저작권과 같이 창작과 동시에 자동으로 발생하며 등록이 필요 없다."], "a": 2, "e": "지식재산권은 저작권(저작 인격권·저작 재산권·저작 인접권)과 산업재산권(특허권·실용신안권·디자인권·상표권)으로 나뉜다. 산업재산권은 특허청에 출원·등록해야 배타적 독점권이 부여된다. 특허권 20년(고도의 발명), 실용신안권 10년(실용적 개량 기술), 디자인권 20년, 상표권 10년(10년마다 갱신 가능해 반영구적)이다.", "w": ["틀린 설명. 고도의 발명은 특허권(20년)이고, 실용신안권은 실용적 개량 기술로 10년이다.", "틀린 설명. 상표권은 10년마다 갱신 가능해 반영구적 권리이다.", "옳은 설명(정답). 저작 인접권의 의미이다.", "틀린 설명. 산업재산권은 특허청에 출원하여 등록받아야 배타적 독점권이 부여된다."]}, {"p": "254", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "디지털 환경의 저작권 침해 행위와 방지 대책에 대한 설명으로 옳은 것은?", "o": ["저작자 표시가 없는 인터넷 그림은 저작권자가 없으므로 자유롭게 퍼 와도 된다.", "가수가 직접 작사·작곡하지 않은 노래를 팬카페에 올리려면 가수의 허락만 받으면 된다.", "방송 프로그램을 사적 이용 목적으로 캡처하는 것은 허용되지만, 캡처본을 인터넷에 올리면 전송권 침해가 될 수 있다.", "가정에서 개인적으로 쓰려고 컴퓨터 프로그램을 복제하는 것도 영리 목적이 아니라면 금지된다."], "a": 2, "e": "사적 이용을 위한 복제는 허용되지만 인터넷에 올리면 전송권 침해가 될 수 있다. 저작자 표시가 없어도 저작권자는 반드시 있다. 가수는 노래를 부르는 데 대한 저작인접권만 있으므로 작사가·작곡가·음반제작자의 허락이 필요하다.", "w": ["틀린 설명. 저작자 표시가 없어도 저작권자는 반드시 있다.", "틀린 설명. 작사가·작곡가·음반제작자에게 허락을 받아야 한다.", "옳은 설명(정답). 사적 복제는 허용되나 업로드는 전송권 침해가 될 수 있다.", "틀린 설명. 가정 등 한정된 장소에서 비영리 개인 사용 목적의 복제는 허용된다."]}, {"p": "257-258", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "디지털 격차와 디지털 포용에 대한 설명으로 옳지 않은 것은?", "o": ["Mori(2011)의 포용적 디지털 전환 3단계 중 마지막 단계는 사용자가 단순 소비자를 넘어 디지털 재화를 소유하고 재창조하는 단계이다.", "디지털 포용은 모든 국민이 디지털 역량을 갖추고 디지털 기술·서비스의 혜택을 공평하게 누리는 것을 의미한다.", "디지털 격차는 접근 격차, 활용 격차, 참여 수준의 격차로 구분된다.", "활용 격차는 컴퓨터 보유나 인터넷 가입 여부 등 정보기기 보유 정도를 말한다."], "a": 3, "e": "정보기기 보유 정도와 이용 가능 여부는 '접근 격차'이다. 활용 격차는 컴퓨터·인터넷 사용능력의 양적 다양성과 질적 유용성, 참여 수준 격차는 정보 생산 활동 참여 정도와 다른 구성원과의 연계 여부이다.", "w": ["맞는 설명. 1단계 접근 보장, 2단계 기초 디지털 문해력, 3단계 재창조이다.", "맞는 설명. 디지털 포용의 정의이다.", "맞는 설명. 디지털 격차의 세 가지 구분이다.", "틀린 설명(정답). 정보기기 보유 정도는 '접근 격차'이다."]}, {"p": "260-261", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "노년학과 기술학을 합성한 개념으로, 1989년 네덜란드에서 처음 소개되어 기술로 노년의 활동적인 삶을 지원하는 학문 분야는?", "o": ["제론테크놀로지(Gerontechnology)", "디지털 사회혁신(DSI)", "AAL(Ambient Assisted Living)", "리빙랩(Living Lab)"], "a": 0, "e": "제론테크놀로지는 노년학과 기술학의 합성어이다. AAL은 고령자의 독립적인 가정생활을 지원하는 EU의 연구개발 프로그램이고, 디지털 사회혁신(DSI)은 디지털 기술로 사회문제를 해결하는 활동이며, 리빙랩은 주민이 일상의 문제를 찾아 해결하는 주민주도 조직이다.", "w": ["정답. 노년학과 기술학을 합성한 제론테크놀로지이다.", "오답. DSI는 디지털 기술로 사회문제를 해결해 효율성과 공공 투명성을 높이는 활동이다.", "오답. AAL은 EU의 고령자 독립생활 지원 연구개발 프로그램이다.", "오답. 리빙랩은 주민이 일상 문제 해결을 주도하는 조직이다."]}, {"p": "273-274", "s": "제3부 1장 교수·학습 방법의 이해", "q": "한 유치원 교사가 자선냄비에 성금하는 동영상을 보여주자 아이들이 이를 주의 깊게 보고 기억했다가 따라 했다. 이를 가장 잘 설명하는 이론은?", "o": ["피아제의 인지적 발달 이론", "파블로프의 고전적 조건화", "스키너의 조작적 조건화", "반두라의 관찰학습 이론"], "a": 3, "e": "반두라의 관찰학습 이론은 타인의 행동을 관찰하고 모방하는 과정에서 학습이 이루어진다고 보며, 이를 주의 집중·기억·재현·동기 유발의 과정으로 설명한다.", "w": ["오답. 피아제는 인지 발달 단계와 동화·조절을 통한 지식 구성을 설명했다.", "오답. 고전적 조건화는 종소리와 먹이처럼 반복 훈련으로 조건 반응을 학습하는 것이다.", "오답. 조작적 조건화는 능동적 행동에 강화(보상)를 주어 행동을 지속시키는 것이다.", "정답. 타인의 행동을 관찰하고 모방하는 관찰학습이다."]}, {"p": "276-277", "s": "제3부 1장 교수·학습 방법의 이해", "q": "학습자의 실제적 발달 수준과 잠재적 발달 수준의 차이를 뜻하는 비고츠키의 개념은?", "o": ["선행조직자", "스캐폴딩", "근접 발달 지대(ZPD)", "동화와 조절"], "a": 2, "e": "근접 발달 지대(Zone of Proximal Development)는 실제적 발달 수준과 잠재적 발달 수준의 차이이며, 교사는 그 차이를 좁혀 나가도록 도와야 한다. 스캐폴딩은 이를 위해 교사가 주는 도움이다.", "w": ["오답. 선행조직자는 오수벨이 강조한 것으로, 새 학습 전에 제공하는 정보이다.", "오답. 스캐폴딩은 학습자가 지적으로 성장하도록 교사가 주는 도움이다.", "정답. 실제적·잠재적 발달 수준의 차이가 근접 발달 지대이다.", "오답. 동화와 조절은 피아제의 지식 구성 개념이다."]}, {"p": "278-279", "s": "제3부 1장 교수·학습 방법의 이해", "q": "교사 중심 교수·학습 방법에 대한 설명으로 옳은 것은?", "o": ["스왑(Schwab)은 학습자를 작은 과학자로 보는 개념학습법을 제안했다.", "오수벨은 새로운 지식을 기존 지식과 연결할 때 학습이 활발해진다고 보고 '선행조직자'의 중요성을 강조했다.", "오수벨은 설명을 듣는 학습자가 인지적으로 수동적인 상태에 있다고 보았다.", "타바는 개념 형성보다 대량의 정보 암기가 먼저 이루어져야 한다고 보았다."], "a": 1, "e": "오수벨은 학습자가 설명을 수용하며 활발한 인지 활동을 하고, 기존 인지 구조를 변화시키면 '유의미 학습'이 일어난다고 보았다. 타바는 개념 형성이 먼저이며 귀납적 사고가 좋다고 했다. 스왑은 학습자 중심의 '탐구학습법'에서 학습자를 작은 과학자로 보았다.", "w": ["틀린 설명. 스왑은 학습자 중심인 '탐구학습법'과 관련된다.", "옳은 설명(정답). 오수벨의 설명법과 선행조직자이다.", "틀린 설명. 오수벨은 학습자가 설명을 들을 때 활발한 인지 활동을 한다고 보았다.", "틀린 설명. 타바는 많은 정보를 처리하려면 개념 형성이 먼저 되어야 한다고 했다."]}, {"p": "280", "s": "제3부 1장 교수·학습 방법의 이해", "q": "4~5명으로 구성된 집단의 구성원들이 각자 맡은 부분을 준비해 와서 다른 구성원과 공유하는 협동 학습 모형은?", "o": ["성취 과제 분담 모형(STAD)", "러닝투게더(Learning Together) 모형", "직소(Jigsaw) 모형", "프로젝트 접근법"], "a": 2, "e": "직소 모형은 상호작용 활성화에 좋지만 누군가 제대로 하지 않으면 집단 전체가 학습 결손을 가진다. STAD는 같은 내용을 함께 공부하며(개별 맞춤 어려움), 러닝투게더는 보상·평가를 집단으로 받아 무임승차자 대응이 어렵다.", "w": ["오답. STAD는 4~5명이 같은 내용을 함께 공부한다.", "오답. 러닝투게더는 협동 수행 후 보상과 평가를 모두 집단으로 받는다.", "정답. 각자 맡은 부분을 준비해 공유하는 것이 직소 모형이다.", "오답. 프로젝트 접근법은 협동 학습 모형이 아니라 별도의 학습자 중심 방법이다."]}, {"p": "288-290", "s": "제3부 1장 교수·학습 방법의 이해", "q": "유아 교수·학습의 원리 중 '오감을 통해 구체적인 사물이나 현상을 직접 경험할 수 있도록 해야 한다'는 원리는?", "o": ["탐색의 원리", "구체성의 원리", "자발성의 원리", "통합의 원리"], "a": 1, "e": "유아 교수·학습의 원리는 자발성, 개별화, 다양성·융통성, 구체성, 탐색, 통합의 원리이다. 구체성의 원리에 따라 일상 도구·놀잇감·시청각 자료와 신체적·비언어적 표현을 활용한다.", "w": ["오답. 탐색의 원리는 호기심을 가지고 스스로 탐색할 때 학습이 된다는 원리이다.", "정답. 오감을 통한 구체적 경험을 강조하는 것이 구체성의 원리이다.", "오답. 자발성의 원리는 유아가 스스로 선택·결정해 활동할 때 유의미한 학습이 된다는 원리이다.", "오답. 통합의 원리는 교육 요소들과 과거 경험이 연결될 때 학습이 잘 된다는 원리이다."]}, {"p": "291", "s": "제3부 1장 교수·학습 방법의 이해", "q": "유아 대상 상호작용 전략 중 '비지시적 유형'에 해당하는 것은?", "o": ["모델 보이기", "시범 보이기", "스캐폴딩 하기", "함께 구성하기"], "a": 0, "e": "지시적 유형은 지시하기·시범 보이기, 중재적 유형은 함께 구성하기·스캐폴딩 하기·지지하기, 비지시적 유형은 촉진하기·모델 보이기·인정하기이다. '모델 보이기'는 제안·지시 없이 자연스럽게 모범을 보이는 것이다.", "w": ["정답. 모델 보이기는 지시 없이 바람직한 행동을 자연스럽게 보이는 '비지시적' 유형이다.", "오답. 시범 보이기는 '지시적' 유형이다.", "오답. 스캐폴딩 하기는 '중재적' 유형이다.", "오답. 함께 구성하기는 '중재적' 유형이다."]}, {"p": "301-303", "s": "제3부 1장 교수·학습 방법의 이해", "q": "아동·청소년 교수·학습의 원리 중 '자기 주도성의 원리와 참여의 원리가 통합된 형태로, 독립심이 강해지는 시기에 타율적 행동이 반항심을 불러일으킬 수 있다는 점을 고려한' 원리는?", "o": ["다양성의 원리", "활동 중심의 원리", "자율 참여의 원리", "맥락화 교육의 원리"], "a": 2, "e": "아동·청소년 교수·학습의 원리는 자율 참여, 맥락화 교육, 다양성, 자기 탐구, 활동 중심, 협동, 창의성 계발의 원리이다.", "w": ["오답. 다양성의 원리는 학습자의 능력이 제각기 다르다는 점을 고려하는 원리이다.", "오답. 활동 중심의 원리는 실천과 체험이 중심이 되어야 한다는 원리이다.", "정답. 자기 주도성 + 참여가 통합된 자율 참여의 원리이다.", "오답. 맥락화 교육의 원리는 삶의 환경·상황·대인관계를 총체적으로 살피는 원리이다."]}, {"p": "302-303", "s": "제3부 1장 교수·학습 방법의 이해", "q": "아동·청소년 교수·학습 활동과 교사의 역할에 대한 설명으로 옳은 것은?", "o": ["인지 능력 개발 지원에서는 허위정보 유통 상황을 고려할 때 비판적 사고보다 암기력이 특히 강조된다.", "경쟁적 활동은 갈등과 대립을 줄이므로 지나치게 자극해도 문제가 없다.", "개별적 활동은 분담과 협력의 방법을 배우기에 가장 적합하다.", "창의성은 유창성·독창성·융통성을 하위 요소로 하며 수렴적 사고와 발산적 사고를 아우르며 발현된다."], "a": 3, "e": "경쟁적 활동은 지나치면 갈등과 대립이 심화하고, 개별적 활동은 자율성을 살리지만 분담·협력을 배우지 못하게 한다. 협동적 활동은 상호의존을 경험하게 한다. 허위정보 유통 상황에서 비판적 사고의 중요성이 특히 강조된다.", "w": ["틀린 설명. 허위정보 상황에서는 비판적 사고의 중요성이 특히 강조된다.", "틀린 설명. 경쟁심을 지나치게 자극하면 갈등과 대립이 심화한다.", "틀린 설명. 개별적 활동은 분담과 협력의 방법을 배우지 못하게 한다는 문제가 있다.", "옳은 설명(정답). 창의성 계발의 원리 내용이다."]}, {"p": "305-306", "s": "제3부 1장 교수·학습 방법의 이해", "q": "온라인 괴롭힘 문제에서 피해자의 처지를 이해하도록 할 때 특히 활용할 수 있으며, 가정된 상황에서 소집단 구성원이 각기 다른 역할을 연기하는 전략은?", "o": ["역할 놀이형", "도제식 교수·학습", "강의형", "멘토링과 코칭"], "a": 0, "e": "역할 놀이는 상황 설정이 모두 가정된 것이라 참여자가 사건과 거리를 확보해 객관적으로 성찰하고, 타자를 연기하며 타인의 입장을 이해하게 한다. 위험하거나 비용이 큰 상황의 실습에는 게임 및 시뮬레이션이 적합하다.", "w": ["정답. 타자를 연기하며 입장을 이해하는 역할 놀이형이다.", "오답. 도제식은 숙련된 전문가를 모방하며 기술을 연마하는 방식이다.", "오답. 강의형은 많은 양의 지식을 전달할 때 쓰는 전략이다.", "오답. 멘토링은 대화를 통해 스스로 문제를 해결하도록 돕고, 코칭은 기능 숙련을 돕는다."]}, {"p": "312-314", "s": "제3부 1장 교수·학습 방법의 이해", "q": "성인 학습자의 특징과 교수·학습 고려 사항으로 옳지 않은 것은?", "o": ["나이가 들면 모든 인지 능력이 같은 속도로 일제히 감퇴하므로 학습 속도를 일률적으로 낮춘다.", "노인 대상 교육에서는 나이 듦을 자연스러운 현상으로 받아들이고 유쾌하게 대응하도록 돕는다.", "노안은 40대부터 나타나는 것으로 알려져 있으므로 글씨 크기를 키우는 등 보완 지원을 한다.", "노년기에는 감각기억과 단기 기억 능력이 떨어지므로 반복을 통해 장기기억으로 이동하도록 돕는다."], "a": 0, "e": "인지 능력의 각 요소는 최고조에 이르는 시기와 저하되는 속도가 제각기 다를 수 있어, 나이가 든다고 인지 능력이 감퇴한다고 할 수는 없다. 학습자의 능력 차이를 고려해 학습 속도와 방법을 유연하게 조정해야 한다.", "w": ["틀린 설명(정답). 인지 요소별 저하 시기와 속도가 다르므로 유연하게 조정해야 한다.", "맞는 설명. 노년기 심리적 특성에 대한 고려이다.", "맞는 설명. 신체적 특성(시력 변화)에 대한 고려이다.", "맞는 설명. 인지적 특성에 대한 고려이다."]}, {"p": "315-317", "s": "제3부 1장 교수·학습 방법의 이해", "q": "성인 대상 교수·학습에서 교사의 역할에 대한 설명으로 옳은 것은?", "o": ["'촉진자'는 새로운 지식이나 특정 기술 습득 교육에 가장 적합하다.", "'전문가'는 시간이 부족하거나 학습자의 지식·경험이 부족할 때 강의·시범·실습으로 효과적으로 학습을 지원한다.", "'강의자'는 학습자의 교사 의존 가능성이 전혀 없다는 장점이 있다.", "'멘토'는 타자 주도적 역할에 속한다."], "a": 1, "e": "타자 주도적 역할: 전문가·기획자·강의자, 자기 주도적 역할: 촉진자·지원가·학습 관리자, 상호주의자: 역할 모델·멘토·학습동반자·개혁가·반추적 실천가. 촉진자는 자기주도학습 경험이 있는 학습자에게 효과적이지만 새로운 지식·기술 습득 교육에는 적합하지 않다.", "w": ["틀린 설명. 촉진자는 새로운 지식이나 특정 기술 습득 교육에 적합하지 않다.", "옳은 설명(정답). 전문가 역할이 효과적인 상황이다.", "틀린 설명. 강의자는 학습자가 교사에게 의존하게 될 가능성이 있어 주의가 필요하다.", "틀린 설명. 멘토는 '상호주의자' 역할에 속한다."]}, {"p": "319-320", "s": "제3부 1장 교수·학습 방법의 이해", "q": "교수 매체에 따른 분류 중 '원격 교육에 쓰이며 짧은 시간에 많은 사람에게 경제적·효율적으로 활용될 수 있는' 매체는?", "o": ["예시적 교수 매체", "조작적 교수 매체", "확산적 교수 매체", "환경적 교수 매체"], "a": 2, "e": "예시적 매체는 언어·시각·청각·시청각·후각 매체, 조작적 매체는 학습자가 직접 기기를 조작하는 기능 개발용 매체, 확산적 매체는 인쇄·방송·인터넷 등 원격 교육 매체(오늘날 이러닝), 환경적 매체는 교수·학습 장소와 물리적 환경이다.", "w": ["오답. 예시적 교수 매체는 예시를 통해 학습 효과를 높이는 매체이다.", "오답. 조작적 교수 매체는 학습자가 직접 조작하며 기능을 개발하는 매체이다.", "정답. 원격 교육에서 쓰이는 확산적 교수 매체이다.", "오답. 환경적 교수 매체는 장소와 물리적 환경을 말한다."]}, {"p": "327", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "홍후조(2002)의 교육과정 기본 질문과 해당 영역의 연결로 옳지 않은 것은?", "o": ["어떻게 가르치고 배울 것인가? – 교육평가", "제대로 가르치고 배우고 있는가? – 교육평가", "왜 그것을 가르치고 배우는가? – 교육목표", "무엇을 가르치고 배울 것인가? – 교육과정"], "a": 0, "e": "'어떻게 가르치고 배울 것인가?'는 교수·학습에 해당한다. 순서는 교육목표 → 교육과정 → 교수·학습 → 교육평가이다.", "w": ["틀린 연결(정답). '어떻게'는 '교수·학습'의 질문이다.", "맞는 연결.", "맞는 연결.", "맞는 연결."]}, {"p": "329-330", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "교수·학습 목표와 성취기준에 대한 설명으로 옳지 않은 것은?", "o": ["학습목표는 장기간 정진해야 달성할 수 있는 목표 하나를 제시하는 것이 가장 효과적이다.", "교수·학습 목표는 핵심역량, 학습목표, 관련교과, 성취기준으로 기술한다.", "학습목표는 학습자의 현재 수준보다 약간 어려운, 도움을 받아 달성할 수 있는 범위(ZPD)로 잡는 것이 효과적이다.", "성취기준 [9국06-05]는 중학교(9) 국어(국) 교과 매체 영역(06)의 다섯 번째 성취기준을 뜻한다."], "a": 0, "e": "학습목표는 지나치게 오래 정진해야 하는 목표보다 단기적으로 성취 가능한 목표를 단계적으로 제시하는 것이 좋고, 가능하면 학습자가 함께 참여해 공동으로 설정하는 것이 바람직하다.", "w": ["틀린 설명(정답). 단기적으로 성취 가능한 목표를 단계적으로 제시하는 것이 좋다.", "맞는 설명. 교수·학습 목표의 기술 항목이다.", "맞는 설명. 근접발달영역(ZPD) 수준의 목표가 효과적이다.", "맞는 설명. 성취기준 코드의 해석이다(학년군-교과-영역-번호)."]}, {"p": "333", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "2022 개정 교육과정이 추구하는 인간상에 해당하지 않는 것은?", "o": ["경쟁력 있는 사람", "자기주도적인 사람", "창의적인 사람", "교양 있는 사람"], "a": 0, "e": "2022 개정 교육과정의 인간상은 자기주도적인 사람, 창의적인 사람, 교양 있는 사람, 더불어 사는 사람이다. 2015 교육과정의 '의사소통 역량'이 '협력적 소통 역량'으로 교체되었고, OECD DeSeCo 프로젝트의 영향을 받았다.", "w": ["해당하지 않음(정답). 네 번째 인간상은 '더불어 사는 사람'이다.", "해당함.", "해당함.", "해당함."]}, {"p": "339", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "교수요목의 일반적 설계 절차(김정숙, 2000)를 순서대로 바르게 나열한 것은?", "o": ["요구 조사 → 내용 선정 → 교육 목적·목표 설정 → 평가 설계 → 배열·조직 → 범주 결정", "내용 범주 결정 → 요구 조사 → 평가 설계 → 교육 목적·목표 설정 → 내용 선정 → 배열·조직", "교육 목적·목표 설정 → 요구 조사 → 내용 범주 결정 → 내용 선정·방법 결정 → 배열·조직 → 평가 설계", "요구 조사 → 교육 목적·목표 설정 → 내용 범주 결정 → 내용 선정·방법 결정 → 배열·조직 → 평가 방법 설계"], "a": 3, "e": "교수요목 설계 절차는 ① 학습자의 요구 조사 → ② 교육 목적 및 목표 설정 → ③ 교육 내용의 범주 결정 → ④ 교육 내용 선정 및 방법 결정 → ⑤ 교육 내용의 배열 및 조직 → ⑥ 평가 방법의 설계이다.", "w": ["오답. 목적·목표 설정이 내용 선정보다 앞선다.", "오답. 요구 조사가 가장 먼저이다.", "오답. 요구 조사가 가장 먼저이다.", "정답. 교재에 제시된 6단계 순서이다."]}, {"p": "348-350", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "교수·학습 지도안에 대한 설명으로 옳지 않은 것은?", "o": ["도입 단계의 가장 주요한 기능은 해당 수업의 학습 목표를 확인하는 것이다.", "정리 단계에서는 해당 수업을 정리하고 간단한 평가를 하며, 다음 차시를 안내한다.", "교수·학습 지도안은 상세한 정도와 관계없이 한 가지 형식만 존재하며 약안·세안의 구분은 없다.", "교수·학습 지도안은 대개 도입-전개-정리의 세 부분으로 구성된다."], "a": 2, "e": "교수·학습 활동은 내용의 상세한 정도에 따라 약안과 세안으로 나뉜다. 지도안은 학습 단계, 학습 요소, 교수·학습활동, 자료 및 유의점으로 기술한다.", "w": ["맞는 설명. 도입의 주요 기능이다.", "맞는 설명. 정리 단계의 기능이다.", "틀린 설명(정답). 상세한 정도에 따라 약안과 세안으로 나뉜다.", "맞는 설명. 지도안의 일반적인 구조이다."]}, {"p": "357-358", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "교수·학습 평가에 대한 설명으로 옳은 것은?", "o": ["절대기준평가는 학생이 다른 학생에 비해 얼마나 잘했는지에 관심을 둔다.", "형성평가는 수업 도중 피드백을 제공하고 교수·학습 방법을 개선해 학습을 증진하기 위해 실시한다.", "신뢰도는 검사가 측정하려는 능력을 얼마나 충실하게 재고 있는지를 의미한다.", "상대평가는 '준거지향평가'라고도 하며, 자격증 시험은 주로 이 방식으로 진행된다."], "a": 1, "e": "타당도는 측정하려는 능력을 얼마나 충실히 재는지, 신뢰도는 얼마나 오차 없이 일관되게 재는지이다. 상대평가는 '규준지향평가'로 다른 학생과의 비교에 관심을 두고, 절대기준평가는 '준거지향·목표지향평가'로 자격증 시험 등이 이 방식이다.", "w": ["틀린 설명. 다른 학생과의 비교는 '상대평가'의 관심사이다.", "옳은 설명(정답). 형성평가의 목적이다.", "틀린 설명. 이는 '타당도'의 설명이다.", "틀린 설명. 상대평가는 '규준지향평가'이며, 자격증 시험은 절대기준평가로 진행된다."]}, {"p": "360-361", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "평가 기준에 따른 평가 요소별로 학습자의 기대 수행 수준을 척도·단계별로 나누어 서술식으로 나타낸 채점 기준표는?", "o": ["총체적 채점표", "분석적 채점 기준표", "성취기준표", "교수요목표"], "a": 1, "e": "분석적 채점 기준표는 학습자에게 과제 수행의 초점을 알려주고 피드백 자료로 활용될 수 있다. 총체적 채점은 영역을 구분하지 않고 종합적으로 판단해 하나의 점수를 부여한다. 교수·학습 평가는 평가 목표, 평가 기준, 평가 준거로 기술한다.", "w": ["오답. 총체적 채점은 과정과 결과를 종합적으로 판단해 하나의 평점을 부여한다.", "정답. 평가 요소별 기대 수행 수준을 단계별로 서술한 것이 분석적 채점 기준표이다.", "오답. 성취기준은 교육과정상 학습 결과의 도달점이다.", "오답. 교수요목은 교육 내용을 주제별 항목으로 조직한 것이다."]}, {"p": "371-372", "s": "제3부 3장 범주1 디지털 시민과 신기술 미디어 수업 사례", "q": "'디지털 시민' 수업의 핵심역량 제시 방법으로 옳은 것은?", "o": ["청년 학습자는 미디어 비판 역량만 다루고 시민 역량은 다루지 않는다.", "디지털 시민 수업의 핵심역량은 미디어 기술 역량 하나뿐이다.", "유아 학습자는 미디어 시민 역량에 초점을 두고, 보호자와의 소통은 배제한다.", "학령기 학습자는 미디어 비판 역량과 미디어 윤리 역량에 초점을 두며, 미디어 비판 역량은 2022 개정 교육과정의 지식정보처리 역량·창의적 사고와 관련된다."], "a": 3, "e": "디지털 시민의 핵심역량은 미디어 비판·윤리·시민 역량이다. 유아는 미디어 윤리 역량에 초점을 두고 보호자와의 소통으로 더 효과적으로 진행하며, 청년은 비판·윤리 역량에 더해 사적·공적 영역의 참여를 강조하는 미디어 시민 역량이 발현되도록 지원한다.", "w": ["틀린 설명. 청년은 비판·윤리 역량에 더해 미디어 시민 역량도 발현되도록 지원한다.", "틀린 설명. 미디어 비판 역량, 미디어 윤리 역량, 미디어 시민 역량이다.", "틀린 설명. 유아는 '미디어 윤리 역량'에 초점을 두며 보호자와의 소통을 통해 더 효과적으로 진행한다.", "옳은 설명(정답). 학령기 학습자의 핵심역량 제시 방법이다."]}, {"p": "374-376", "s": "제3부 3장 범주1 디지털 시민과 신기술 미디어 수업 사례", "q": "'디지털 시민' 수업의 평가와 소외계층 배려에 대한 설명으로 옳은 것은?", "o": ["노년기 학습자용 워크시트는 다른 연령층과 같은 글씨 크기로 제작해야 형평성이 유지된다.", "학령기 저학년에서 O, X로 양분할 수 있는 단순한 평가 요소는 체크리스트를 활용하는 것이 효율적이다.", "평가 준거 척도는 단계를 세분화할수록 저학년도 교사가 의도한 질적 수준을 정확히 파악한다.", "평가는 인지적 영역에 집중하고 정의적 영역은 제외한다."], "a": 1, "e": "척도를 세분화하면 면밀한 평가가 가능하지만 교사가 질적 차이를 파악하기 어렵고 저학년도 목표 수준을 이해하기 어려워, 간단한 요소는 체크리스트를 권한다. 평가는 인지적·정의적 영역이 균형 있게 이루어져야 하며, 노년기용 자료는 글씨와 이미지를 크게 하고 자막·재생 속도 조절이 가능한 영상을 제공한다.", "w": ["틀린 설명. 노년기 학습자용 자료는 글씨와 이미지 크기를 크게 할 것을 권장한다.", "옳은 설명(정답). 단순 요소는 2단계 체크리스트가 효율적이다.", "틀린 설명. 세분화할수록 저학년이 질적 수준을 파악하지 못할 수 있다는 단점이 있다.", "틀린 설명. 인지적 영역과 정의적 영역의 평가가 균형 있게 이루어져야 한다."]}, {"p": "402-403", "s": "제3부 3장 범주1 디지털 시민과 신기술 미디어 수업 사례", "q": "생성형 AI에 좋은 질문을 하는 방법(김덕진, 2023)으로 옳지 않은 것은?", "o": ["원하는 답을 얻지 못하면 추가 정보를 주며 꼬리에 꼬리를 무는 질문을 이어 간다.", "챗GPT는 검색엔진처럼 출처가 확인된 정보만 제공하므로 답변을 별도로 검증할 필요가 없다.", "질문은 구체적일수록 좋다.", "질문의 맥락이나 배경 정보, 예시를 함께 준다."], "a": 1, "e": "챗GPT는 검색엔진이 아니라 이미 배운 것을 토대로 생성하는 AI여서 답변이 틀릴 수 있으므로, 특히 논문·보고서 등 정확성이나 출처가 필요한 경우 검증해야 한다. 이 밖에 '8세 천재 아이처럼 다루기', 명확한 단어 사용, 올바른 형식 갖추기, 개방형 질문 활용 등이 제시된다.", "w": ["맞는 방법. 탐정처럼 추가 정보를 주며 질문을 이어간다.", "틀린 방법(정답). 생성형 AI의 답변은 틀릴 수 있어 검증이 필요하다.", "맞는 방법. 지시를 구체적으로 해야 한다.", "맞는 방법. 맥락·배경 정보를 주면 더 잘 답한다."]}, {"p": "411-413", "s": "제3부 3장 범주2 디지털 활용과 창작 수업 사례", "q": "'디지털 활용' 수업 사례에 대한 설명으로 옳지 않은 것은?", "o": ["디지털 활용 교육은 기술적 역량만 다루며 데이터의 사회적 가치나 윤리적 활용 같은 비판적 역량은 다루지 않는다.", "수업 유형은 대면 수업, 가능하다면 컴퓨터실 수업을 제시한다.", "핵심역량으로 미디어 비판 역량과 미디어 시민 역량을 제시한다.", "노년 학습자에게는 데이터·콘텐츠의 검색과 선별 및 관리가 주요 교육 내용이 될 수 있다."], "a": 0, "e": "디지털 활용 교육은 기술적 역량에 1차적 초점을 두지만, 정보를 목적에 맞게 탐색·선별·분석·활용하려면 비판적 사고도 필요하므로 데이터의 사회적 가치와 결과의 윤리적 활용 같은 비판적 역량도 중요하게 다룬다.", "w": ["틀린 설명(정답). 기술적 역량과 함께 비판적 역량도 중요하게 다룬다.", "맞는 설명. 표 2-1의 수업 유형이다.", "맞는 설명. 표 2-2의 핵심역량이다.", "맞는 설명. 노년 학습자의 주요 교육 내용이다."]}, {"p": "427-428", "s": "제3부 3장 범주2 디지털 활용과 창작 수업 사례", "q": "'미디어 창작' 수업에서 학습자별 수업 유형 선정 시 고려할 점으로 옳지 않은 것은?", "o": ["노년 학습자는 디지털 정보화 수준이 낮아 스마트폰 이용률도 낮으므로 아날로그 매체만 활용한다.", "유·아동은 누리과정과 연계하고, 제작 기법보다 예술적 경험에 초점을 둔 놀이 중심 콘텐츠 제작이 효과적이다.", "청소년은 미디어 역량이 가장 활발하게 발달하는 시기이므로 기초 이해를 넘어 프로젝트 기획형 수업을 추천한다.", "성인은 실생활이나 직무와 연계한 실용적 교육을 설계하고, 진단 평가로 개별화 수업을 모색한다."], "a": 0, "e": "노년 학습자는 디지털 정보화 수준이 낮음에도 스마트폰·스마트 TV 등 미디어 이용률은 높다는 점을 염두에 두고, 사전 조사로 익숙한 미디어 양식을 활용한다. 미디어 활용 방법의 반복 학습과 콘텐츠 진위 판별 문제도 다룬다.", "w": ["틀린 설명(정답). 노년층은 정보화 수준은 낮지만 스마트폰 등 미디어 이용률은 높다.", "맞는 설명. 유·아동 대상 미디어 창작의 방향이다.", "맞는 설명. 숏폼 제작 등 프로젝트 기획형 수업이다.", "맞는 설명. 성인 학습자 대상 설계 방향이다."]}, {"p": "435-437", "s": "제3부 3장 범주2 디지털 활용과 창작 수업 사례", "q": "'미디어 창작' 수업의 차시 구성과 평가에 대한 설명으로 옳지 않은 것은?", "o": ["미디어 콘텐츠 창작에서는 제작만큼 편집 과정이 중요하므로 자르기·자막·음향 조정 실습을 포함한다.", "평가 준거 예시에서 '창작 과정에 대한 설명'의 배점이 50%로 가장 높다.", "미디어 창작의 사후 평가는 총괄 평가를 우선으로 한다.", "인원이 많으면 카메라맨·편집자·감독·배우·작가 등 역할을 나눈 팀 프로젝트로 진행하고, 역할을 바꿔 반복 기회를 준다."], "a": 2, "e": "과정 평가를 적용한 후 미디어 창작의 사후 평가는 '형성 평가'를 우선으로 한다. 제작 과정의 기능·테크놀로지 활용도·응용 능력을 판단할 수 있도록 피드백 성격의 형성 평가가 적합하다. 배점은 개념·구성요소 30%, 창작 과정 50%, 유통 결과 성찰 20%이다.", "w": ["맞는 설명. 편집의 중요성이다.", "맞는 설명. 창작 과정 설명이 50%이다.", "틀린 설명(정답). 사후 평가는 '형성 평가'를 우선으로 한다.", "맞는 설명. 1분가량 숏폼, 교실 내 배경 등으로 한두 차시 내에 수행하게 한다."]}, {"p": "448-449", "s": "제3부 3장 범주3 미디어 재현과 정보판별 수업 사례", "q": "'미디어 재현' 수업에서 학습 대상자별 고려 사항으로 옳지 않은 것은?", "o": ["노년 학습자는 문자 중심으로 정보를 습득해 왔으므로 미디어 리터러시에 대한 집중적인 학습이 필요하다.", "이주배경 학습자 수업에서는 미디어의 고정관념을 이해하기 전이라도 논쟁적인 콘텐츠를 먼저 제시해 문제의식을 높인다.", "중등 학습자에게는 재현의 개념과 특징, 재현 콘텐츠의 의미와 영향력을 중점적으로 교육한다.", "청년 학습자는 자신이 창작한 콘텐츠도 특정 관점에서 재현된 것이며 타인에게 영향을 끼칠 수 있음을 인식하게 한다."], "a": 1, "e": "학습자가 미디어에 고정관념이 남용되고 있음을 이해하지 못한 상태에서 논쟁적인 콘텐츠를 제시하는 것은 지양해야 한다. 미디어 비판이 아닌 콘텐츠 내용과 차별적 인식에만 초점이 갈 수 있기 때문이다.", "w": ["맞는 설명. 노년기 학습자의 특성과 교육 방향이다.", "틀린 설명(정답). 고정관념 이해 전 논쟁적 콘텐츠 제시는 지양해야 한다.", "맞는 설명. 정체성을 형성해 가는 시기임을 고려한다.", "맞는 설명. 청년 학습자 대상 교육의 방향이다."]}, {"p": "453-454", "s": "제3부 3장 범주3 미디어 재현과 정보판별 수업 사례", "q": "'미디어 재현'(5차시) 교수요목의 차시 구성에 대한 설명으로 옳지 않은 것은?", "o": ["충분한 이론 학습보다 실습을 먼저 진행해야 학습자의 흥미가 유지되므로 첫 차시부터 분석 실습을 한다.", "1차시 재현의 개념과 특징 이해 → 2~4차시 광고·뉴스·드라마/영화의 관점과 의도 분석 → 5차시 재현 콘텐츠 분석 실습으로 구성한다.", "이론적 개념 이해에서 시작해 구체적 방법을 설명하고, 이후 학습자가 실제 미디어를 분석하는 과정으로 구성한다.", "분석 활동은 처음에 교사의 시범을 중심으로 제시한 뒤 학습자 스스로 분석하게 한다."], "a": 0, "e": "학습자 스스로 콘텐츠 분석 실습을 하는 능력을 길러주는 데 중점을 두되, 충분한 이론적 학습이 된 후에 실습을 하는 것이 중요하다. 개념 이해와 기능 습득이 분리되지 않도록 한다. 학습자 수준에 따라 차시를 줄이거나 늘릴 수 있다.", "w": ["틀린 설명(정답). 충분한 이론적 학습 후에 실습을 하는 것이 중요하다.", "맞는 설명. 표 3-3의 교수요목 체계이다.", "맞는 설명. 차시 구성 원칙이다.", "맞는 설명. 교사 시범 후 학습자 분석으로 나아간다."]}, {"p": "460-462", "s": "제3부 3장 범주3 미디어 재현과 정보판별 수업 사례", "q": "'정보판별과 확증편향' 수업에서 노년기 학습자에게 확증편향을 가르칠 때 유의할 점으로 가장 적절한 것은?", "o": ["노년기 학습자는 콘텐츠 사용 습관이 고착화되지 않았으므로 습관 점검은 생략한다.", "유튜브 알고리즘 등 반복 노출 현상은 다루지 않는다.", "본인의 정치적 신념과 직결된 정치 이슈를 핵심 사례로 활용해 경각심을 높인다.", "확증편향을 정치적 이슈 등 개인 신념과 관련된 내용으로 설명하지 않고, 허위정보의 유형·유통 방법·비즈니스 모델 등 사회 구조를 거시적으로 이해하게 한다."], "a": 3, "e": "노년기 학습자는 자신만의 콘텐츠 사용 습관이 고착화되어 있으므로 확증편향 성향을 스스로 인식하게 하되, 정치적 신념에 반감을 갖지 않도록 구체적 사례로 개념을 중립적으로 설명한다. 유튜브 알고리즘을 예로 반복 노출 현상도 인식시킨다.", "w": ["오답. 노년기 학습자는 콘텐츠 사용 습관이 고착화되어 있다.", "오답. 유튜브 알고리즘 등을 예로 들어 반복 노출 현상을 인식시킨다.", "오답. 정치적 신념과 관련된 내용으로 설명하지 않도록 한다.", "정답. 사회 구조를 거시적으로 이해하도록 이끈다."]}, {"p": "466-467", "s": "제3부 3장 범주3 미디어 재현과 정보판별 수업 사례", "q": "'정보판별과 확증편향'(6차시) 수업의 차시 구성 시 주의할 점으로 교재가 강조한 것은?", "o": ["사례부터 제시하면 학습자가 사례에만 관심을 가져 이론적 이해와 분석 방법에 흥미를 잃기 쉬우므로 이론 학습 후 사례를 적용한다.", "확증편향 개념은 다루지 않고 허위정보 유형만 다룬다.", "팩트 체킹 실습은 학습자 혼란을 줄이기 위해 생략한다.", "사례부터 제시해야 학습자의 흥미가 이론 학습으로 자연스럽게 이어진다."], "a": 0, "e": "교수요목은 허위정보 유형과 특성 → 사회적 영향력 → 정보 판별 방법 → 확증편향 개념 → 사례 탐구 → 정보 분석 평가의 실제 순이다. 이론 학습 후 사례를 적용해 일상의 경험이 허위정보·확증편향과 관련됨을 인지하게 하고, 마지막에 뉴스 자료 등을 팩트 체킹하는 실습을 한다.", "w": ["정답. 이론 학습 후 사례를 적용하도록 한다.", "오답. 4차시가 확증편향의 개념, 5차시가 사례 탐구이다.", "오답. 구체적인 뉴스 자료를 팩트 체킹하는 실습을 한다.", "오답. 교재는 사례 우선 제시의 문제점을 지적한다."]}, {"p": "484-485", "s": "제3부 3장 범주4 미디어 산업과 책임 수업 사례", "q": "'미디어 산업과 소비자'(4차시) 교수요목의 차시 구성으로 옳은 것은?", "o": ["1차시 미디어 산업의 개념·유형·구조 → 2차시 비즈니스 모델·마케팅 전략과 광고 → 3차시 미디어 산업과 정책 → 4차시 미디어 산업과 소비자", "1차시 미디어 산업과 소비자 → 2차시 정책 → 3차시 비즈니스 모델 → 4차시 개념·유형", "1차시 광고 제작 실습 → 2차시 뒷광고 사례 → 3차시 개념 → 4차시 정책", "1차시 사이버 폭력 → 2차시 공유 → 3차시 협업 → 4차시 혐오 표현"], "a": 0, "e": "3차시에서는 공공성과 상업성이라는 미디어 산업의 본질과 독과점 방지, 편집권 독립 보장, 망중립성, 광고 규제 등 주요 정책을 다루고, 4차시에서는 광고 메시지를 비판적으로 수용하고 1인 미디어·숏폼 문화의 '생비자' 개념을 탐색한다.", "w": ["정답. 교재의 4차시 교수요목 체계이다.", "오답. 개념·유형이 1차시, 소비자가 4차시이다.", "오답. 교재의 차시 구성과 다르다.", "오답. 이는 '협력적 소통과 책임 있는 이용'(5차시) 구성과 유사하다."]}, {"p": "495-497", "s": "제3부 3장 범주4 미디어 산업과 책임 수업 사례", "q": "'협력적 소통과 책임 있는 이용' 수업의 핵심역량으로 제시된 것을 모두 고른 것은?", "o": ["미디어 비판 역량, 미디어 시민 역량", "미디어 기술 역량, 미디어 창의 역량, 미디어 소통 역량", "미디어 기술 역량, 미디어 소통 역량, 미디어 윤리 역량, 미디어 시민 역량", "미디어 기술 역량, 미디어 비판 역량"], "a": 2, "e": "이 주제는 디지털 미디어 소통 시 가져야 할 정의적 태도(공감, 상호 존중, 책임감, 윤리의식)에 초점을 둔 영역으로, 핵심역량은 미디어 기술·소통·윤리·시민 역량이다. 수업 유형은 '디지털 미디어 소통에 대한 탐구 학습'이다.", "w": ["오답. 미디어 산업과 소비자, 정보판별 단원의 핵심역량이다.", "오답. 미디어 창작 단원의 핵심역량이다.", "정답. 표 4-11의 네 가지 핵심역량이다.", "오답. 미디어 재현 단원의 핵심역량이다."]}, {"p": "502-504", "s": "제3부 3장 범주4 미디어 산업과 책임 수업 사례", "q": "'협력적 소통과 책임 있는 이용' 수업의 평가에 대한 설명으로 옳은 것은?", "o": ["평가 준거 예시에서 '공유와 협업의 수행'에 40%로 가장 높은 배점을 둔다.", "협력적 소통과 책임에 대한 이해는 개념을 단순 암기했는지 확인하는 문항으로 평가하는 것이 가장 바람직하다.", "미디어 공유와 협업 평가는 총괄 평가를 우선으로 한다.", "미디어 공유와 협업 평가 영역은 내용 이해를 평가하는 데 가장 적합하다."], "a": 0, "e": "배점은 소통과 상호작용 이해 30%, 공유와 협업 수행 40%, 문제 인식과 대응 방안 30%이다. 미디어 공유와 협업 평가는 '형성 평가'를 우선으로 하며, 이 영역은 내용 이해 평가에는 적합하지 않다. 단순 암기 확인보다 실제 문제 상황 사례에 개념을 적용하는 심화형 문항을 사용한다.", "w": ["옳은 설명(정답). 공유와 협업 수행이 40%이다.", "틀린 설명. 실제 문제 상황 사례에 개념을 적용하는 심화형 평가 문항을 사용한다.", "틀린 설명. 미디어 공유와 협업 평가는 형성 평가를 우선으로 한다.", "틀린 설명. 공유와 협업 평가 영역은 내용 이해 평가에 적합하지 않다."]}, {"p": "521-522", "s": "제3부 3장 범주5 미디어 윤리와 안전 수업 사례", "q": "장애 학습자를 위해 적용하는 '보편적 학습 설계(UDL)' 원리에 대한 설명으로 옳은 것은?", "o": ["모든 학습자에게 동일한 한 가지 방식의 자료만 제공해 공정성을 높인다.", "학습의 어려움의 원인을 학습자의 능력이 아니라 학습자의 요구를 반영하지 않은 학습 설계에 두며, 다양한 경로(시각·청각 자료 등)를 제공한다.", "장애 학습자만을 대상으로 한 분리 교육 원리이다.", "학습의 어려움의 원인을 학습자의 능력 부족에서 찾는다."], "a": 1, "e": "보편적 학습 설계(Universal Design for Learning)는 개인의 다양성·개별화에 초점을 두고 모든 학습자의 성공적 학습을 위해 다양한 경로를 제공한다. 글쓰기가 어려운 학생은 그림이나 말로 표현하게 하고, 듣기가 어려운 학생에게는 자막이 충실한 영상을 제공한다.", "w": ["틀린 설명. 다양한 방식으로 자료를 제공한다.", "옳은 설명(정답). UDL의 핵심 관점이다.", "틀린 설명. 모든 학습자의 참여를 촉진하는 원리이다.", "틀린 설명. 원인을 학습자의 능력이 아닌 학습 설계에 둔다."]}, {"p": "524", "s": "제3부 3장 범주5 미디어 윤리와 안전 수업 사례", "q": "교재가 제시한 노년 교육 대상자의 디지털 역량 특징으로 옳은 것은?", "o": ["디지털 윤리 능력과 보안 능력이 모두 매우 높다.", "파일 전송, 악성코드 검사 등 기본 정보 활용 능력이 청년층보다 높다.", "키오스크 이용 능력과 앱 설치 능력이 매우 높다.", "인신공격·비방 자제 등 디지털 윤리 능력은 높지만, 타인의 불법 행위에 대한 자기 보호 역량이 낮아 디지털 보안 능력이 낮다."], "a": 3, "e": "노년 교육 대상자는 파일 전송·악성코드 검사·문서 작성 등 기본 정보 활용 능력과 와이파이 설정·앱 설치·키오스크 이용 능력이 낮다. 디지털 윤리 능력은 높지만 자기 보호 역량이 낮아, 피싱·파밍·스미싱 등 디지털 범죄의 인지와 대응을 중심으로 구성할 필요가 있다.", "w": ["틀린 설명. 보안 능력이 낮다.", "틀린 설명. 기본 정보 활용 능력이 낮다.", "틀린 설명. 앱 설치·키오스크 이용 능력이 낮다.", "옳은 설명(정답). 윤리 능력은 높고 보안 능력은 낮다."]}, {"p": "538-541", "s": "제3부 3장 범주5 미디어 윤리와 안전 수업 사례", "q": "'디지털 문제해결' 수업에서 학습 대상자별 고려 사항과 핵심역량 제시 방법으로 옳지 않은 것은?", "o": ["유아의 디지털 문제는 부모의 양육 스타일과 태도의 영향이 크므로 스마트폰 중독 예방 수업은 양육자 교육과 함께 이루어져야 한다.", "성인 학습자는 꼭 필요한 부분(무인 단말기, 응용 소프트웨어)은 생산적으로 활용하고 그렇지 않은 부분은 사용을 줄이는 균형에 중점을 둔다.", "노년기 학습자는 미디어 기술 역량 신장을 목표로 노인대학·노인 복지 센터 등을 중심으로 학습을 전개한다.", "청소년은 정보 판별이 필요 없으므로 미디어 비판 역량을 제외하고 미디어 기술 역량만 제시한다."], "a": 3, "e": "청소년 시기에는 정보의 홍수 속에서 진위를 판단하는 미디어 비판 역량이 반드시 필요하고, 적극적인 생산자·소비자로서 미디어 소통 역량과 미디어 윤리 역량도 강조해야 한다. 디지털 문제해결 단원의 핵심역량은 기술·비판·소통·윤리·시민 역량 다섯 가지이다.", "w": ["맞는 설명. 유아 대상 수업은 양육자 교육과 병행한다.", "맞는 설명. 성인 대상 수업의 중점이다.", "맞는 설명. 노년기 학습자 대상 방향이다.", "틀린 설명(정답). 청소년에게는 미디어 비판 역량이 반드시 필요하다."]}]}, {"name": "4회차", "r": "201~562쪽", "questions": [{"p": "203", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "맥퀘일(McQuail, 2010)이 정리한 '뉴스의 재현에서 보이는 편향의 전형'에 해당하지 않는 것은?", "o": ["국제 뉴스는 물리적으로 가깝고 부유하며 힘 있는 나라에 집중된다.", "사회적 고위층과 공적 위치에 있는 사람들을 정보원으로 주로 이용한다.", "사회적 소수자의 목소리를 주류보다 우선해 비중 있게 다룬다.", "폭력적인 범죄나 개인의 범죄를 과도하게 다루는 반면 사회의 실제 위험 현실은 간과한다."], "a": 2, "e": "맥퀘일은 뉴스가 엘리트 중심, 현상 유지 지지, 자민족 중심, 남성 중심 가치를 반영하며 사회적 소수자는 소외·무시되거나 비난받는다고 정리했다.", "w": ["해당함. 국제 뉴스의 지리적·경제적 편중이다.", "해당함. 고위층을 정보원으로 삼아 그 견해를 과잉 보도하는 경향이다.", "해당하지 않음(정답). 뉴스에서 사회적 소수자는 오히려 소외되고 무시되거나 비난받는다.", "해당함. 폭력·개인 범죄 과잉 보도와 실제 위험 간과이다."]}, {"p": "205", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "슈메이커와 리스(Shoemaker & Reese, 2014)의 게이트키핑 다중 계층 모델에서 '광고주의 요구에 따라 특정 브랜드에 불리한 뉴스가 보도되지 않는 경우'가 속하는 차원은?", "o": ["개인 차원", "미디어 외부 요인 차원", "이데올로기적 차원", "미디어 관행(루틴) 차원"], "a": 1, "e": "다섯 차원은 개인(언론인의 성별·인종·계층), 관행(뉴스 가치·취재 관행), 조직(편집 방침·소유주 이념), 외부 요인(독자·광고주·정부), 이데올로기(자본주의 vs 사회주의 국가의 보도 기준) 차원이다.", "w": ["오답. 개인 차원은 언론인의 성별·인종·계층·교육수준 등의 영향이다.", "정답. 독자·시청자·광고주·정부 등은 미디어 외부 요인 차원이다.", "오답. 이데올로기 차원은 체제에 따른 보도 기준의 근본적 차이 등이다.", "오답. 관행 차원은 언론인들이 공유하는 뉴스 가치 등에 따른 선택이다."]}, {"p": "210-212", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "디지털 시대 정보 환경에 대한 설명으로 옳지 않은 것은?", "o": ["인포데믹은 적절한 기술 규제만 갖추면 완전히 제거할 수 있는 현상이다.", "데이터 스모그는 데이비드 셴크가 인터넷상 쓰레기 같은 정보의 과잉을 지칭한 말이다.", "인포데믹은 정보(information)와 전염병(epidemic)의 합성어로, WHO가 코로나19 팬데믹과 관련해 사용했다.", "탈진실 시대는 객관적 사실보다 감정과 개인적 신념에 의한 호소가 여론 형성에 더 큰 영향을 미치는 현상을 말한다."], "a": 0, "e": "인포데믹은 디지털 기술의 빠른 발전과 연결성 때문에 생기는 현상으로 완전히 제거할 수는 없지만 관리는 가능하다. 정보의 질 향상 정책과 함께 이용자의 비판적 평가와 건전한 정보 소비 습관이 중요하다.", "w": ["틀린 설명(정답). 인포데믹은 완전히 제거될 수 없지만 관리는 가능하다.", "맞는 설명. 셴크(1997)가 '데이터 스모그'라 칭했다.", "맞는 설명. WHO가 2020년 코로나19와 관련해 사용했다.", "맞는 설명. 탈진실 시대의 정의이다."]}, {"p": "212-213", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "허위정보의 문제점과 대응에 관한 설명으로 옳지 않은 것은?", "o": ["'신기함 가설'에 따르면 허위정보가 진실보다 새롭고 이색적이어서 더 많이 공유된다.", "정보 자체가 사실이라면 맥락을 벗어나 사용되더라도 선전 선동의 도구가 될 수 없다.", "정보가 과도한 불안·공포·분노를 일으킨다면 그 정보가 그런 반응을 끌어내려는 것은 아닌지 자문해야 한다.", "MIT 연구(Vosoughi 외, 2018)에서 트위터상 거짓은 진실보다 더 많이, 더 빠르게 확산되었다."], "a": 1, "e": "교재는 정보 자체가 사실일지라도 문맥을 벗어나 사용되면 선전 선동(propaganda)의 무기로 변질될 수 있다고 경고한다. 대응 방법으로 출처 검증, 저자 확인, 내용 깊이 읽기, 게시 날짜 확인, 풍자 여부 판별, 개인 편향성 인지, 감정적 반응 점검, 전문가 상담을 제시한다.", "w": ["맞는 설명. 신기함 가설(novelty hypothesis)의 내용이다.", "틀린 설명(정답). 사실인 정보도 맥락을 벗어나면 선전 선동 무기로 변질될 수 있다.", "맞는 설명. '감정적 반응 점검'에 해당한다.", "맞는 설명. 거짓은 진실보다 70% 더 많이 리트윗되고 약 6배 빠르게 도달했다."]}, {"p": "216-217", "s": "제2부 2장 범주3 미디어 재현과 정보판별", "q": "동질적인 그룹 안에서 개인의 기존 의견이 더 강해지거나 극단적으로 변하는 현상은?", "o": ["정보 피로 증후군", "탈진실", "집단 극화(group polarization)", "인포데믹"], "a": 2, "e": "집단 극화는 추천 알고리즘과 반향실 효과의 문제점으로 제시된다. 스토너(1961)는 동질 집단의 일원일 때 개인보다 더 위험한 결정을 내린다는 것을 발견했다. 대응 전략으로는 알고리즘 투명성 강화·감시, 사용자 교육 및 인식 제고가 있다.", "w": ["오답. 정보 피로 증후군은 정보과부하로 인한 수면·집중력 등의 부정적 증상이다.", "오답. 탈진실은 객관적 사실보다 감정과 신념이 여론에 더 큰 영향을 미치는 현상이다.", "정답. 동질 집단에서 의견이 더 극단화되는 현상이 집단 극화이다.", "오답. 인포데믹은 잘못된 정보가 빠르게 퍼지는 현상이다."]}, {"p": "226", "s": "제2부 2장 범주4 미디어 산업과 책임", "q": "미디어 산업 변화에 따른 '미디어 1.0~4.0 시대' 설명으로 옳지 않은 것은?", "o": ["미디어 4.0 시대는 클라우드·빅데이터·IoT·AI가 통합된 디지털 전환과 맥을 같이하며 콘텐츠 생산에 AI가 참여한다.", "미디어 1.0 시대는 언론사·대기업 등 전문제작자가 공급하는 콘텐츠를 수동적으로 소비하던 시대이다.", "미디어 2.0 시대는 프로슈머들이 개방·참여·공유를 특징으로 콘텐츠를 재생산·소비하기 시작한 시대이다.", "미디어 3.0 시대는 대형 플랫폼 주도가 더욱 강화되어 퍼블릭 액세스가 축소된 시대이다."], "a": 3, "e": "미디어 3.0 시대는 모바일과 소셜 네트워크의 변화로 열리며, 대형 플랫폼 주도에서 벗어나 개인의 다양한 취향과 지역 기반 이슈를 담고 퍼블릭 액세스가 점차 확대되는 시대이다. 1.0에서 4.0으로 갈수록 정보와 콘텐츠 생산량이 기하급수적으로 증가한다.", "w": ["맞는 설명. 데이터 사이언스 기반 디지털 전환과 맥을 같이한다.", "맞는 설명. 전문제작자 중심의 수동적 소비 시대이다.", "맞는 설명. 개인이 콘텐츠를 생산하는 프로슈머의 시대이다.", "틀린 설명(정답). 3.0 시대는 대형 플랫폼 주도에서 벗어나고 퍼블릭 액세스가 '확대'되는 시대이다."]}, {"p": "228-229", "s": "제2부 2장 범주4 미디어 산업과 책임", "q": "미디어 윤리와 허위정보 대응에 대한 설명으로 옳은 것은?", "o": ["허위정보 대응은 이용자 개인의 책임이므로 기업과 기술의 역할은 필요하지 않다.", "넓은 의미의 미디어 윤리는 정보를 생산·전달하는 저널리즘의 직업윤리에 한정된다.", "허위정보에 대응하려면 미디어 기업·디지털 기술 기업·이용자가 함께 협업해야 하며, 이용자는 미디어 리터러시 교육으로 정보 분별력을 함양할 수 있다.", "좁은 의미의 미디어 윤리는 AI·빅데이터 등 새롭게 부상하는 미디어 전반에 관한 규범적 논의이다."], "a": 2, "e": "좁은 의미의 미디어 윤리는 정보를 생산·전달하는 미디어의 공적 가치와 책무를 전제한 윤리이고, 넓은 의미는 AI·빅데이터 등 새로 부상하는 미디어 전반에 관한 규범적 논의이다. 허위정보는 기업·기술·사람의 총체적 협업의 산물이므로 함께 대응해야 한다.", "w": ["틀린 설명. 기업은 자율적 제어장치를, 기술 기업은 AI 윤리 준칙과 할루시네이션 해소 노력을 해야 한다.", "틀린 설명. 직업윤리에 한정된 것은 '좁은 의미'이다.", "옳은 설명(정답). 기업·기술·사람이 함께 협업해야 한다.", "틀린 설명. 이는 '넓은 의미'의 미디어 윤리이다."]}, {"p": "232, 239", "s": "제2부 2장 범주4 미디어 산업과 책임", "q": "EU 「디지털서비스법(DSA)」에 대한 설명으로 옳지 않은 것은?", "o": ["EU 인구 1% 이상을 이용자로 가진 플랫폼은 대형 온라인 플랫폼으로서 외부 감사 의무를 진다.", "2023년 8월 25일부터 EU 전역에서 시행되었다.", "온라인 플랫폼은 유통 콘텐츠가 광고인지, 광고주가 누구인지, 맞춤형 광고의 기준이 무엇인지 밝혀야 한다.", "오프라인에서 불법인 콘텐츠는 온라인 플랫폼에서도 유통되어서는 안 된다."], "a": 0, "e": "DSA의 3대 특징은 불법 콘텐츠에 대한 플랫폼 책임 강화, 투명성 의무 부과, 대형 온라인 플랫폼 규제이다. 대형 온라인 플랫폼은 EU 전체 인구의 10% 이상을 이용자로 가진 플랫폼으로, 자료 공개·데이터 공유·외부 독립 단체 감사 의무를 진다.", "w": ["틀린 설명(정답). 기준은 EU 전체 인구의 '10% 이상'이다.", "맞는 설명. 2023년 8월 25일부터 시행되었다.", "맞는 설명. 투명성 의무 부과의 내용이다.", "맞는 설명. 불법 콘텐츠에 대한 플랫폼 책임 강화의 내용이다."]}, {"p": "233", "s": "제2부 2장 범주4 미디어 산업과 책임", "q": "소비자가 광고의 주장과 호소를 평가할 때 고려할 기준으로 교재가 제시한 세 가지에 해당하지 않는 것은?", "o": ["공정성: 경쟁 제품을 부당하게 폄하하지 않는가", "화제성: 광고가 SNS에서 얼마나 많이 공유되었는가", "사실성: 주장이 사실에 근거하는가", "신뢰성: 신뢰할 수 있는가"], "a": 1, "e": "소비자는 광고의 주장과 호소에 대해 사실성, 신뢰성, 공정성을 평가해야 한다. 광고 규제의 궁극적 목적은 부당한 광고를 방지하고 올바른 정보에 기반한 소비자의 선택권을 보장하는 것이다.", "w": ["해당함. 공정성이다.", "해당하지 않음(정답). 화제성은 교재의 평가 기준이 아니다.", "해당함. 사실성이다.", "해당함. 신뢰성이다."]}, {"p": "237", "s": "제2부 2장 범주4 미디어 산업과 책임", "q": "사이버폭력과 혐오표현에 대한 설명으로 옳은 것은?", "o": ["사이버스토킹은 「스토킹범죄의 처벌 등에 관한 법률」에 따라 처벌된다.", "사이버폭력 예방은 법·제도적 노력만으로 충분하며 교육은 필요하지 않다.", "혐오표현은 다수자의 속성을 이유로 한 비판적 표현을 뜻한다.", "현행법상 혐오표현을 직접적으로 규제하는 단일 법률이 이미 시행 중이다."], "a": 0, "e": "사이버폭력 예방·대응에는 개인적·사회적·법·제도적 노력이 모두 필요하다. 명예훼손은 형법 제307조, 사이버스토킹은 스토킹처벌법으로 처벌한다. 혐오표현은 사회적 소수자의 속성을 이유로 차별·혐오하거나 이를 선동하는 표현이며, 현행법상 직접 규제하는 법률은 없다(혐오표현규제법안은 2018년 발의 후 철회).", "w": ["옳은 설명(정답). 사이버스토킹은 스토킹처벌법에 따라 처벌된다.", "틀린 설명. 개인적·사회적·법·제도적 노력이 모두 필요하며 미디어 리터러시 교육이 지속되어야 한다.", "틀린 설명. 혐오표현은 '사회적 소수자'의 속성을 이유로 한 차별·혐오 표현이다.", "틀린 설명. 현행법상 혐오표현을 직접 규제하는 법률은 없다."]}, {"p": "245-246", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "디지털 권리 보호 동향과 해당 문서의 연결로 옳지 않은 것은?", "o": ["OECD(2022) – 혁신 친화적 AI 규제 접근: 경쟁과 혁신의 촉진, 번영하는 민주주의", "UN 아동권리위원회(2021) – 일반 논평 제25호: 차별 금지, 아동 이익 최우선, 생존·발달 보장, 아동 의견 존중", "EU(2022) – 유럽 디지털 권리와 원칙에 관한 선언문: 인간 중심의 디지털 전환", "미국(2022) – 인공지능 권리장전 청사진: 알고리즘에 의한 차별로부터 보호, 인적 대안 고려"], "a": 0, "e": "'혁신 친화적 접근(A pro-innovation approach to AI regulation)'은 영국(2022)의 문서이다. OECD(2022)는 「디지털 시대의 권리」 보고서에서 표현의 자유, 개인정보 보호, 필수재로서 인터넷 접근권을 다뤘다.", "w": ["틀린 연결(정답). 이는 영국의 문서이다. OECD는 「디지털 시대의 권리」 보고서를 발표했다.", "맞는 연결. 일반 논평 제25호의 네 가지 원칙이다.", "맞는 연결. EU 선언문은 사람 중심의 안전하고 지속 가능한 디지털 전환을 중심으로 한다.", "맞는 연결. 미국 AI 권리장전 청사진의 기본 원칙이다."]}, {"p": "246-247", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "「개인정보보호법」상 개인정보와 개인정보자기결정권에 대한 설명으로 옳지 않은 것은?", "o": ["해당 정보만으로는 특정 개인을 알아볼 수 없더라도 다른 정보와 쉽게 결합해 알아볼 수 있으면 개인정보에 해당한다.", "법인의 상호, 영업 소재지, 임원 정보, 영업 실적도 개인정보로 보호된다.", "정보주체는 자신의 개인정보 열람을 요구할 수 있고, 열람 후 정정 또는 삭제를 요구할 수 있다.", "개인정보를 제3자에게 제공할 때는 정보주체의 동의를 받아야 한다."], "a": 1, "e": "개인정보의 주체는 살아있는 자연인이다. 법인·단체는 주체가 아니므로 법인의 상호·영업 소재지·임원 정보·영업 실적은 개인정보보호법의 보호 범위에 해당하지 않는다. 다른 법령이 수집 대상으로 명시한 개인정보는 삭제를 요구할 수 없다.", "w": ["맞는 설명. 결합 용이성이 있으면 개인정보이다.", "틀린 설명(정답). 법인 정보는 개인정보보호법의 보호 대상이 아니다.", "맞는 설명. 열람·정정·삭제 요구권이다(다른 법령에서 수집 대상으로 명시된 경우 삭제 불가).", "맞는 설명. 제3자 제공 시 정보주체의 동의가 필요하다."]}, {"p": "248-249", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "데이터권에 대한 설명으로 옳지 않은 것은?", "o": ["데이터는 무체물로서 민법상 물건에 해당하지 않아 소유권의 대상이 될 수 없다.", "데이터 3법 개정을 통해 가명 정보를 도입하고 본인신용정보관리업(마이데이터)을 허가하였다.", "본인신용정보관리업은 개인신용정보의 전송요구권(right to data portability)을 행사해 금융 서비스를 이용하게 한 것이다.", "데이터 3법은 「개인정보 보호법」, 「저작권법」, 「전기통신사업법」을 말한다."], "a": 3, "e": "데이터 3법은 「개인정보 보호법」, 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」, 「신용정보의 이용 및 보호에 관한 법률」이다.", "w": ["맞는 설명. 데이터는 무체물이라 소유권의 대상이 아니다.", "맞는 설명. 데이터 3법 개정의 내용이다.", "맞는 설명. 마이데이터의 의미이다.", "틀린 설명(정답). 데이터 3법은 개인정보 보호법, 정보통신망법, 신용정보법이다."]}, {"p": "252-253", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "지식재산권 침해와 대응에 대한 설명으로 옳지 않은 것은?", "o": ["저작물을 SNS에 올릴 때 출처와 링크를 표시하는 것으로 저작권자의 허가를 대신할 수 없다.", "특허권의 보호 범위는 특허 청구 범위에 기재된 내용으로 정해진다.", "상표의 유사 여부는 상품 출처의 혼동 가능성을 기준으로 판단한다.", "상표권 침해는 상표권자가 고소해야만 형사처벌이 가능한 친고죄이다."], "a": 3, "e": "상표권 침해는 소비자도 위조 상품으로 피해를 입을 수 있으므로 상표권자가 고소하지 않아도 형사처벌이 가능하다. 분쟁 조정은 산업재산권 분쟁 조정 위원회(산업재산권), 한국저작권위원회(저작권)를 통해 할 수 있다.", "w": ["맞는 설명. 출처 표시로 허가를 대신할 수 없다.", "맞는 설명. 특허 청구 범위가 보호 범위를 정한다.", "맞는 설명. 출처의 혼동 가능성이 기준이다.", "틀린 설명(정답). 상표권 침해는 고소 없이도 형사처벌이 가능하다."]}, {"p": "254-256", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "악성코드에 감염된 피해자 PC를 조작해 정상 홈페이지에 접속해도 가짜 사이트로 유도한 뒤 금융정보를 탈취하는 사이버 금융 범죄는?", "o": ["메모리해킹", "피싱(Phishing)", "파밍(Pharming)", "스미싱(Smishing)"], "a": 2, "e": "피싱은 금융기관을 가장한 이메일로 가짜 사이트에 유도, 스미싱은 문자메시지(SMS) 속 링크로 악성코드를 설치, 메모리해킹은 PC 메모리에 상주한 악성코드로 보안카드 앞뒤 2자리만 입력해도 부당 인출하는 수법이다. 경찰청은 디지털 범죄를 정보통신망 침해 범죄, 정보통신망 이용 범죄, 불법 콘텐츠 범죄로 구분한다.", "w": ["오답. 메모리해킹은 정상 사이트에서 이체 정보를 가로채는 수법이다.", "오답. 피싱은 금융기관을 가장한 이메일로 가짜 사이트 접속을 유도한다.", "정답. 감염된 PC에서 정상 주소로 접속해도 가짜 사이트로 유도하는 것이 파밍이다.", "오답. 스미싱은 문자메시지 링크를 통해 악성코드를 설치한다."]}, {"p": "259-260", "s": "제2부 2장 범주5 미디어 윤리와 안전", "q": "미디어 신기술로 인한 문제에 대응하는 자세로 옳지 않은 것은?", "o": ["생성형 인공지능을 활용한 경우 그 활용 여부를 표시한다.", "인공지능 챗봇은 대화 내용을 학습하지 않으므로 기업 보안 정보를 입력해도 안전하다.", "인공지능이 생성한 자료는 사실 여부를 반드시 다시 검증한다.", "메타버스에서는 아바타 건너편에 인간이 있다는 사실을 인지하고 현실의 사회적 가치를 준수한다."], "a": 1, "e": "AI 챗봇과 나눈 대화 내용은 AI에게 학습될 수 있으므로 개인정보나 기업 보안 정보를 입력하지 않아야 한다. 2023년 미국에서는 한 변호사가 AI에 의존해 거짓 판례가 담긴 자료를 제출해 문제가 되었다.", "w": ["맞는 설명. 생성형 AI 활용 여부를 표시한다.", "틀린 설명(정답). 대화 내용이 학습될 수 있어 개인정보·보안 정보를 입력하지 않아야 한다.", "맞는 설명. AI 환각(hallucination) 때문에 반드시 재검증해야 한다.", "맞는 설명. 메타버스 이용 시 갖춰야 할 자세이다."]}, {"p": "271-273", "s": "제3부 1장 교수·학습 방법의 이해", "q": "교수·학습에 대한 관점과 설명의 연결로 옳지 않은 것은?", "o": ["이해적인 관점 – 상호작용을 관찰·기록해 그 의미를 해석하며, 평가자의 주관적 해석에 그칠 수 있다는 한계가 있다.", "예술적인 관점 – 교사는 배우, 학습자는 관객, 교수·학습 내용은 시나리오로 보며 학습자는 수동적 관객이어야 한다고 본다.", "통합적인 관점 – 교수·학습을 기술과 예술의 결합체로 보며 교사의 기술적 전문성, 교육적 감각, 통찰력을 '기본'으로 본다.", "전통적인 관점 – 교수·학습의 기술적 측면에 집중하며 구성 요소별 체크리스트로 객관적으로 분석한다."], "a": 1, "e": "예술적인 관점은 교수·학습을 연극 같은 예술 작품으로 보되, 교사와 학습자의 질 높은 상호작용을 강조하며 학습자가 수동적인 관객이 아니라 '적극적인 참여자'가 되어야 한다고 본다.", "w": ["맞는 연결. 그래서 자기 성찰에만 의존한 평가는 지양해야 한다.", "틀린 연결(정답). 예술적 관점은 학습자가 수동적 관객이 아니라 적극적인 참여자여야 한다고 본다.", "맞는 연결. 통합적 관점의 내용이다.", "맞는 연결. 표준화된 요소에 집중하느라 맥락성을 소홀히 할 수 있다는 한계가 있다."]}, {"p": "274-276", "s": "제3부 1장 교수·학습 방법의 이해", "q": "정보처리 이론과 관련 학자의 설명으로 옳지 않은 것은?", "o": ["듀이의 반성적 사고 다섯 단계는 모든 학습자에게 고정된 순서로 동일하게 적용된다.", "정보처리 이론은 인간의 인지 과정을 컴퓨터의 정보 입력·저장·출력 과정에 비유한다.", "듀이는 반성적 사고를 제안, 지성화, 가설 형성, 추론, 가설검증의 다섯 단계로 제시했다.", "브루너의 발견학습 결과는 동작적·영상적·상징적 표상 방식으로 표현할 수 있다."], "a": 0, "e": "듀이의 반성적 사고 다섯 단계는 고정되어 있지 않으며 개인차가 있을 수 있다. 브루너는 학습자가 스스로 탐구하며 '발견의 기쁨'을 경험하도록 해야 한다고 강조했다.", "w": ["틀린 설명(정답). 다섯 단계는 고정되어 있지 않고 개인차가 있을 수 있다.", "맞는 설명. 정보 투입 → 부호화 → 저장 → 인출 과정이다.", "맞는 설명. 반성적 사고의 다섯 단계이다.", "맞는 설명. 행동(동작적), 그림·이미지(영상적), 말·글(상징적) 표상이다."]}, {"p": "276", "s": "제3부 1장 교수·학습 방법의 이해", "q": "구성주의 이론에 대한 설명으로 옳은 것은?", "o": ["구성주의는 인지적 구성주의와 사회문화적 구성주의로 나뉘며, 인간을 '능동적 지식의 구성자'로 본다.", "피아제는 인지 발달을 감각운동기 → 구체적 조작기 → 전조작기 → 형식적 조작기 순으로 보았다.", "비고츠키는 지식이 사회문화와 무관하게 개인 내부에서만 형성된다고 보았다.", "인간을 환경적 자극에 수동적으로 반응하는 존재로 본다."], "a": 0, "e": "구성주의는 인간을 능동적 지식의 구성자로 본다. 인지적 구성주의는 개인의 인지 작용을, 사회문화적 구성주의는 사회적 상호관계를 중시한다. 피아제의 발달 단계는 감각운동기 → 전조작기 → 구체적 조작기 → 형식적 조작기이다.", "w": ["옳은 설명(정답). 구성주의의 두 갈래와 인간관이다.", "틀린 설명. 전조작기가 구체적 조작기보다 앞선다.", "틀린 설명. 비고츠키는 지적 발달이 사회문화적 영향을 많이 받는다고 보았다.", "틀린 설명. 이는 행동주의 이론의 인간관이다."]}, {"p": "279-280", "s": "제3부 1장 교수·학습 방법의 이해", "q": "듀이가 말한 '교육적 가치가 있는 문제'의 두 가지 요건으로 옳은 것은?", "o": ["교사가 정답을 알고 있을 것, 시험에 출제될 것", "학습자가 호기심을 품거나 궁금해할 것, 해결이 사회적·문화적·지적 가치가 있을 것", "단계가 짧을 것, 혼자 해결할 수 있을 것", "교과서에 수록될 것, 결과를 수치로 측정할 수 있을 것"], "a": 1, "e": "듀이는 문제 해결학습의 가치를 학생의 정신 활동 활성화, 특히 반성적 사고 능력 증진에 두었다. 교육적 가치가 있는 문제는 학습자의 호기심과 사회적·문화적·지적 가치를 모두 충족해야 한다.", "w": ["오답. 교재에 제시된 요건이 아니다.", "정답. 학습자의 호기심과 해결의 사회적·문화적·지적 가치이다.", "오답. 교재에 제시된 요건이 아니다.", "오답. 교재에 제시된 요건이 아니다."]}, {"p": "287", "s": "제3부 1장 교수·학습 방법의 이해", "q": "유아의 연령별 발달 특징과 교수·학습 참고 사항의 연결로 옳은 것은?", "o": ["5세 이상 – 낯선 사람에게 두려움을 가지므로 첫 시간에 친밀하게 다가갈 전략이 핵심이다.", "3세 – 복합 정서를 이해하므로 미디어 안전·표현 교육에 도덕감을 적극 활용한다.", "3세 – 모든 발달의 전환점(transitional period)으로 알려진 시기", "4세 – 직관적 사고를 하고 기억력이 발달하므로 수업 끝에 회상하여 말하는 활동을 넣으면 좋다."], "a": 3, "e": "4세는 모든 발달의 전환점으로, 직관적 사고와 기억력 발달 특징이 있어 회상 활동이 효과적이다. 3세는 낯선 사람·환경에 두려움을 가져 친밀감 형성 전략이 필요하고, 5세 이상은 복합 정서와 도덕감이 발달한다.", "w": ["틀린 연결. 낯선 사람에 대한 두려움은 '3세'의 정서적 특징이다.", "틀린 연결. 복합 정서 이해와 도덕감 발달은 '5세 이상'의 특징이다.", "틀린 연결. 발달의 전환점은 '4세'이다.", "옳은 연결(정답). 4세의 인지 발달 특징과 교수·학습 참고 사항이다."]}, {"p": "288-289", "s": "제3부 1장 교수·학습 방법의 이해", "q": "유아 교수·학습의 '개별화의 원리'에서 말하는 개인 내의 차이에 해당하는 예는?", "o": ["남아와 여아의 미디어 이용 시간이 다르다.", "한 아동의 인지 능력은 빠르게 발달하지만 신체·운동 능력은 느리게 발달한다.", "유아마다 성장 배경과 생활 방식이 다르다.", "이민 온 유아는 한국에서 자란 유아와 한국어 능력이 다르다."], "a": 1, "e": "개인 간 차이는 성별·나이·기질·능력·생활 방식·성장 배경으로 인한 유아들 사이의 차이이고, 개인 내 차이는 한 유아가 가진 여러 능력 간의 발달 방식·수준의 차이이다. 따라서 한 가지 능력으로 다른 능력을 짐작해서는 안 된다.", "w": ["오답. 성별에 따른 '개인 간' 차이이다.", "정답. 한 아동 안에서 능력별 발달 수준이 다른 '개인 내' 차이이다.", "오답. 성장 배경·생활 방식은 '개인 간' 차이 요인이다.", "오답. 성장 배경에 따른 유아 간 차이로 '개인 간' 차이이다."]}, {"p": "299-301", "s": "제3부 1장 교수·학습 방법의 이해", "q": "아동·청소년의 발달 특징에 대한 설명으로 옳지 않은 것은?", "o": ["아동기는 대략 만 6~10세로, 인지 능력이 구체적인 수준에서 논리적인 수준으로 발달한다.", "초기 청소년기(10~13세)는 직접적·구체적 사고를 하며 눈으로 확인하거나 직접 경험해야 인정하는 경우가 있다.", "중기 청소년기(14~16세)는 구체적·추상적 사고가 모두 가능하지만 정보를 통합하는 능력은 아직 부족하다.", "후기 청소년기(16~19세)는 여럿이 어울리기보다 또래 집단에 강하게 뭉쳐 다니며 권위에 도전하는 특성이 두드러진다."], "a": 3, "e": "친구들과 강한 유대로 뭉쳐 다니고 권위에 도전하는 것은 '초기 청소년기'의 사회적 특징이다. 후기 청소년기는 인간관계가 안정되고 여럿이 어울리기보다 개인적인 친교에 집중하며, 독립적 결정과 타협이 가능해진다.", "w": ["맞는 설명. 아동기의 시기와 인지 발달 특징이다.", "맞는 설명. 초기 청소년기의 인지적 특징이다.", "맞는 설명. 중기 청소년기의 특징이다.", "틀린 설명(정답). 이는 초기 청소년기의 특징이며, 후기 청소년기는 개인적 친교에 집중한다."]}, {"p": "302", "s": "제3부 1장 교수·학습 방법의 이해", "q": "아동·청소년 교수·학습의 '다양성의 원리'의 이론적 근거로 교재가 제시한 것은?", "o": ["에릭슨의 심리사회적 발달 단계", "스키너의 조작적 조건화", "피아제의 인지 발달 단계론", "가드너의 다중지능이론"], "a": 3, "e": "가드너(1997)의 다중지능이론은 아동별로 특별히 잘하는 분야가 있고, 같은 분야에서도 능력 차이가 있다는 것을 보여준다. 미디어 교사는 학습자의 미디어 역량이 제각기 다른 속도로 발전할 수 있음을 이해해야 한다.", "w": ["오답. 에릭슨은 성인기 발달 단계에서 다룬다.", "오답. 스키너는 행동주의 이론에서 다룬다.", "오답. 피아제는 구성주의의 인지 발달 이론에서 다룬다.", "정답. 가드너의 다중지능이론이 근거이다."]}, {"p": "305-306", "s": "제3부 1장 교수·학습 방법의 이해", "q": "집단 교수·학습 전략의 예시에 대한 설명으로 옳지 않은 것은?", "o": ["포럼은 1인 이상의 전문가와 25인 이상의 집단으로 구성되며 구성원 모두 직접 토론에 참여한다.", "브레인스토밍에서는 아이디어의 질을 높이기 위해 제출된 아이디어를 즉시 비판하고 걸러낸다.", "심포지엄은 소수의 사람이 공식 발표를 하고 토론하며, 청중과의 상호 의견 교환은 이루어지지 않는다.", "패널 토론은 3~6명의 패널이 대화 형태로 토론하고 청중은 경청한다."], "a": 1, "e": "브레인스토밍은 제약이나 금지규정 없이 비형식적으로 진행되며, 제출된 아이디어에 대한 부정과 비판은 허용되지 않고 모든 아이디어를 동등하게 취급한다.", "w": ["맞는 설명. 포럼의 특징이다.", "틀린 설명(정답). 브레인스토밍에서는 아이디어에 대한 부정과 비판이 허용되지 않는다.", "맞는 설명. 심포지엄의 특징이다.", "맞는 설명. 패널 토론의 특징이다."]}, {"p": "311", "s": "제3부 1장 교수·학습 방법의 이해", "q": "에릭슨(Erikson, 1985)의 발달 단계에 따른 성인기의 특성 연결로 옳은 것은?", "o": ["노년기 – 생산성 대 침체 – 지혜", "청년기 – 생산성 대 침체 – 배려", "장년기 – 친밀감 대 소외 – 사랑", "노년기 – 자아 통합 대 절망 – 지혜"], "a": 3, "e": "청년기: 친밀감 대 소외(잠재 능력: 사랑), 장년기(성인 초기·중기): 생산성 대 침체(배려), 노년기(성인 후기): 자아 통합 대 절망(지혜).", "w": ["틀린 연결. 노년기의 과제는 자아 통합 대 절망이다.", "틀린 연결. 생산성 대 침체·배려는 장년기이다.", "틀린 연결. 친밀감 대 소외·사랑은 청년기이다.", "옳은 연결(정답). 노년기는 자아 통합 대 절망, 잠재 능력은 지혜이다."]}, {"p": "314-315", "s": "제3부 1장 교수·학습 방법의 이해", "q": "성인 교수·학습의 원리 중 '학습자의 자기 결정성과 해방적 속성을 강조하며, 미디어 불평등이 심화하지 않도록 학습권을 보장하는' 원리는?", "o": ["역량 개발의 원리", "문제 해결의 원리", "주체화의 원리", "자기 주도적 학습의 원리"], "a": 2, "e": "주체화의 원리는 미디어 접근성·활용 능력 차이를 완화하는 교육, 잠재력 개발 교육, 일상 경험을 활용한 미디어 역량 발현 교육을 강조한다.", "w": ["오답. 역량 개발의 원리는 변화에 대처하는 능력을 기르는 원리이다.", "오답. 문제 해결의 원리는 생활 속에서 학습한 지식·기능을 발휘하도록 지원하는 원리이다.", "정답. 자기 결정성과 해방적 속성, 학습권 보장을 강조하는 주체화의 원리이다.", "오답. 자기 주도적 학습의 원리는 학습자가 스스로 교육을 주도해야 한다는 원리이다."]}, {"p": "317-318", "s": "제3부 1장 교수·학습 방법의 이해", "q": "성인 미디어교육에서 '미디어 활용 능력 및 기능 교육'에 가장 많이 활용되는 방법은?", "o": ["역할극과 토의", "지역사회 교육 공동체 구성", "강연회와 패널 토의", "개인 지도와 시범 및 실습"], "a": 3, "e": "정보·지식 제공 교육에는 강연회·강의·패널 토의, 활용 능력·기능 교육에는 개인 지도와 시범·실습(실연법, 참관·관찰법, 현장 연수), 태도·가치관 교육에는 강의·토의·역할극·매체 활용 교육을 주로 활용한다.", "w": ["오답. 태도 및 가치관 교육에 주로 활용된다.", "오답. 학습자 조직 방식에 따른 지역사회 중심 교수·학습의 특징이다.", "오답. 정보 및 지식 제공 교육에 많이 활용된다.", "정답. 기본 개념 강의 → 교사 시범 → 학습자 실습의 흐름이다."]}, {"p": "326", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "교육 목적과 교육 목표에 대한 설명으로 옳은 것은?", "o": ["교육 목적과 교육 목표는 같은 개념으로 구분하지 않는다.", "교육 목표는 보편적이고 일반적인 수준에서 진술하며 교육 목적의 토대가 된다.", "교육 목적은 단편적이고 단기적인 지향점으로 구체적이고 명료하게 진술한다.", "교육 목표는 교육 목적에 도달하기 위한 과정에서 이루어내야 하는 단편적이고 단기적인 지향점이다."], "a": 3, "e": "교육 목적은 종합적·장기적 지향점으로 보편적·일반적 수준에서 진술하며 교육 목표의 기본 토대가 된다. 교육 목표는 목적에 도달하기 위한 단편적·단기적 지향점으로 구체적·명료하게 진술한다.", "w": ["틀린 설명. 교육 목적(장기·포괄)과 교육 목표(단기·구체)는 구분된다.", "틀린 설명. 보편적·일반적 진술은 교육 '목적'이며, 목적이 목표의 토대가 된다.", "틀린 설명. 이는 '교육 목표'의 설명이다.", "옳은 설명(정답). 교육 목표의 정의이다."]}, {"p": "328", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "교사의 강의를 동영상이나 읽기 자료로 만들어 학생들이 가정에서 사전 학습하게 하고, 교실에서는 토의·토론·문제해결·프로젝트 등 적용 활동을 하는 수업 방식은?", "o": ["플립드 러닝", "직접교수법", "강의식 수업", "블렌디드 수업"], "a": 0, "e": "플립드 러닝(거꾸로 교실)의 설명이다(이지연 외, 2014). 교재는 미디어 관련 수업에서 블렌디드 수업이나 플립드 러닝 같은 다양한 수업 유형을 시도해 볼 수 있다고 제시한다. 교수·학습 정보는 학습 대상자, 수업 유형, 학습 주제로 기술한다.", "w": ["정답. 사전 학습 후 교실에서 적용 활동을 하는 플립드 러닝이다.", "오답. 직접교수법은 교사가 직접 설명하고 시범을 보이는 교수 모형이다.", "오답. 강의식 수업은 교실에서 교사가 지식을 전달하는 방식이다.", "오답. 블렌디드 수업은 다양한 수업 유형을 섞어 구안하는 방식이다."]}, {"p": "331", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "교육 목표의 진술과 행동 목표에 대한 설명으로 옳은 것은?", "o": ["행동 목표는 교사의 행동으로 진술하는 것이 기본 원칙이다.", "행동 목표는 수업 목표가 달성되었을 때 학습자가 보이게 될 도달점 행동으로 나타나며, 행동과 내용의 두 측면을 모두 포함해야 한다.", "명세적 진술에는 관찰 가능성을 고려할 필요가 없다.", "'안다', '이해한다', '파악한다'처럼 폭넓게 해석될 수 있는 동사로 진술하는 것을 명세적 진술이라 한다."], "a": 1, "e": "일반적 진술은 '안다·이해한다' 등 추상적 동사, 명세적 진술은 '정의한다·구별한다·계산한다' 등 관찰 가능한 구체적 동사를 사용한다. 행동 목표는 교사가 아닌 학습자의 행동으로, 도달점 행동으로 진술한다.", "w": ["틀린 설명. 교육 목표는 교사가 아닌 '학습자'의 행동으로 진술해야 한다.", "옳은 설명(정답). 도달점 행동과 행동·내용의 두 측면이다.", "틀린 설명. 명세적 진술은 관찰 가능한 구체적 행동으로 표현한다.", "틀린 설명. 이는 '일반적 진술'이다."]}, {"p": "337-339", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "교수요목(syllabus)에 대한 설명으로 옳지 않은 것은?", "o": ["교수요목은 한 교과의 교육 내용을 주제별 항목으로 조직하여 열거한 것이다.", "교수요목은 교육과정의 하위 요소로 볼 수 있다.", "과정 지향적 교수요목은 학습 과제·과업과 활동의 과정을 중시하며, 절차적 접근에서는 교사의 전문성이 그만큼 더 요구된다.", "결과 지향적 교수요목은 학습자가 수업 중 수행하는 과제와 활동 과정을 가장 중시한다."], "a": 3, "e": "결과 지향적(Product-oriented) 교수요목은 학습의 '결과'를 강조하며 구조적·상황적·개념·기능적 접근이 있다. 과제와 활동 과정을 중시하는 것은 과정 지향적(Process-oriented) 교수요목이다. 다중(혼합) 교수요목은 여러 요소를 혼합해 장점을 살린다.", "w": ["맞는 설명. 교수요목의 정의이다.", "맞는 설명. 가르칠 내용을 구체화·배열한다는 점에서 교육과정의 하위 요소이다.", "맞는 설명. 교수 자료를 사전에 선정하기 힘들어 교사의 전문성이 요구된다.", "틀린 설명(정답). 과제·활동 과정을 중시하는 것은 '과정 지향적' 교수요목이다."]}, {"p": "342", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "우리나라 교육과정에서 1차시로 간주하는 시간의 연결로 옳은 것은?", "o": ["초등학교 40분, 중학교 40분, 고등학교 50분", "초·중·고 모두 50분", "초등학교 45분, 중학교 50분, 고등학교 55분", "초등학교 40분, 중학교 45분, 고등학교 50분"], "a": 3, "e": "초등학교 40분, 중학교 45분, 고등학교 50분을 1차시로 간주한다. 교수요목체계는 차시, 교수·학습 활동 개요, 교수·학습 활동 자료로 기술한다.", "w": ["오답.", "오답.", "오답.", "정답. 40분 / 45분 / 50분이다."]}, {"p": "351-352", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "교육과정 운영의 기본 원리 중 '교육기관과 교사가 부당한 간섭에서 벗어나 독립적으로 자기 결정과 실천을 할 수 있음을 인정하는' 원리는?", "o": ["효율성의 원리", "합목적성의 원리", "합법성의 원리", "자율성의 원리"], "a": 3, "e": "교육과정 운영의 기본 원리는 합목적성, 합법성, 학습자 존중, 자율성, 효율성의 원리이다. 자율성의 원리는 교사가 합법적으로 위임된 권한을 행사하며 전문가 집단으로서 업무를 수행하게 한다.", "w": ["오답. 효율성의 원리는 최소 투입으로 최대 효과를 올리는 원리이다.", "오답. 합목적성의 원리는 교육목표 달성에 부합해야 한다는 원리이다.", "오답. 합법성의 원리는 합헌적이고 법률에 적합해야 한다는 원리이다.", "정답. 부당한 간섭에서 벗어난 독립적 자기 결정이 자율성의 원리이다."]}, {"p": "358-359", "s": "제3부 2장 수업 설계 및 평가 원리", "q": "평가 유형에 대한 설명으로 옳지 않은 것은?", "o": ["서답형 평가는 문항 제작은 쉽지만 채점이 어렵고 시간이 오래 걸린다.", "선다형 평가는 양질의 문항을 제작하기 쉽지만 채점 기준이 모호하다.", "진단평가는 수업 시작 전 학습자의 출발점 행동을 측정·확인한다.", "총괄평가는 집단 간 성적 비교 정보를 제공하고 교육의 장기적인 질적 관리에 활용될 수 있다."], "a": 1, "e": "선다형 평가는 양질의 문항 제작이 비교적 어렵고 오래 걸리지만 채점이 간편하고 채점 기준이 명료하다. 피시험자의 독해력이 영향을 줄 가능성이 크다.", "w": ["맞는 설명. 서답형 평가의 특징이다.", "틀린 설명(정답). 선다형은 문항 제작이 어렵지만 채점이 간편하고 채점 기준이 명료하다.", "맞는 설명. 진단평가의 정의이다.", "맞는 설명. 총괄평가의 활용이다."]}, {"p": "369-370", "s": "제3부 3장 범주1 디지털 시민과 신기술 미디어 수업 사례", "q": "'디지털 시민' 수업 설계 시 학습 대상자별 수업 유형 선정에 대한 설명으로 옳지 않은 것은?", "o": ["초등 고학년~중학생은 익숙한 디지털 매체를 활용해 탐구 수업 또는 프로젝트 수업을 중심으로 구상한다.", "청년 학습자는 프로젝트 활동이나 소논문 작성 등 심층적으로 디지털 미디어를 활용하는 수업을 진행한다.", "노년 학습자는 디지털 기기에 익숙하므로 기초 실습을 생략하고 곧바로 사회 참여 토론 수업을 진행한다.", "유아~초등 저학년은 놀이 활동, 조작 활동, 체험 활동을 활용한 수업 유형을 선택한다."], "a": 2, "e": "노년 학습자는 주로 아날로그 형태의 정보를 다뤄왔으므로 디지털 매체·도구 이해부터 사회 참여까지 순차적·점진적으로 익히는 실습형 수업을 구상하고, 노인 복지 회관·노인 대학·경로당 등에서 밀착형 코치와 피드백으로 디지털 격차를 줄인다.", "w": ["맞는 설명. 책임 있는 미디어 생활을 실천하는 탐구·프로젝트 수업이다.", "맞는 설명. 청년은 이미 PPT 산출물에 익숙하므로 더 심층적인 형태로 진행한다.", "틀린 설명(정답). 노년 학습자는 디지털 기기 이해부터 순차적·점진적으로 익히는 실습형 수업을 제안한다.", "맞는 설명. 인지적·신체적 기능이 성장 중인 '디지털 새싹'을 고려한다."]}, {"p": "373-374", "s": "제3부 3장 범주1 디지털 시민과 신기술 미디어 수업 사례", "q": "'디지털 시민' 교수요목(3차시)의 차시 구성 원칙과 유의사항으로 옳지 않은 것은?", "o": ["3차시는 디지털 시민성과 미디어 리터러시의 관련성을 탐구한다.", "개념을 먼저 정의한 뒤 사례로 내려가는 연역적 차시 구성을 원칙으로 한다.", "1차시는 디지털 사회에서 미디어의 종류와 영향력을 탐구한다.", "2차시는 디지털 시민의 권리(표현의 자유, 정보에 대한 권리 등)와 역할·책무를 탐구한다."], "a": 1, "e": "교재는 연역적 차시 구성보다 '귀납적' 차시 구성을 제안한다. 학습자가 일상에서 경험하는 구체적 사례를 통해 개념적 이해에 도달하도록 구성한다.", "w": ["맞는 설명. 3차시 주제이다.", "틀린 설명(정답). 구체적 사례에서 개념으로 나아가는 귀납적 차시 구성을 권한다.", "맞는 설명. 1차시 주제이다.", "맞는 설명. 2차시 주제이다."]}, {"p": "378-380", "s": "제3부 3장 범주1 디지털 시민과 신기술 미디어 수업 사례", "q": "'브레인 라이팅(Brain Writing)' 기법에 대한 설명으로 옳지 않은 것은?", "o": ["6명이 3가지 아이디어를 5분 내에 기록해 돌리는 '6-3-5 기법'이라고도 불린다.", "반드시 두 명 이상이 함께해야 하며 혼자서는 활용할 수 없다.", "떠오르는 아이디어를 말이 아닌 글로 써서 표현하는 전략이다.", "내성적이어서 타인 앞에서 말하기를 꺼리는 모둠원의 참여를 이끌 수 있다."], "a": 1, "e": "브레인 라이팅은 브레인스토밍을 할 시간적 여유가 없어 '혼자라도' 아이디어를 내야 할 때 활용할 수 있으며, 브레인스토밍의 문제점을 보완한다. 6-3-5 규칙을 반드시 지키지 않아도 모둠 수업에서 생각을 글로 발산·수렴하는 기법으로 활용 가능하다.", "w": ["맞는 설명. 30분에 108개의 아이디어를 얻는 것을 목표로 했다.", "틀린 설명(정답). 혼자서도 아이디어를 낼 때 활용할 수 있다(교재 연습문제 1번).", "맞는 설명. 말이 아닌 글로 표현한다.", "맞는 설명. 내성적인 학습자의 참여를 독려한다."]}, {"p": "402, 406", "s": "제3부 3장 범주1 디지털 시민과 신기술 미디어 수업 사례", "q": "'신기술 미디어' 수업 사례에 대한 설명으로 옳지 않은 것은?", "o": ["교육 목표에는 생성형 AI·알고리즘·빅데이터를 활용한 문제 해결과 과제 수행이 포함된다.", "만다라트 기법은 중앙에 대주제를 쓰고 사방으로 관련 아이디어를 발산하는 기법이다.", "평가 준거에서는 '신기술 미디어를 대하는 올바른 태도'에 가장 높은 배점(30점)을 둔다.", "교수요목은 인공지능, 알고리즘, 빅데이터, 가상공간을 다루는 8차시로 구성된다."], "a": 2, "e": "평가 준거 예시의 배점은 개념과 특성 20, 도구와 활용 방법 30, 문제 해결 능력 30, 사회적 영향력 10, 올바른 태도 10(총 100점)이다.", "w": ["맞는 설명. 신기술 미디어의 교육 목표 ②이다.", "맞는 설명. 만다라트 기법의 설명이다.", "틀린 설명(정답). 올바른 태도는 10점이며, 30점은 도구·활용 방법과 문제 해결 능력이다.", "맞는 설명. 8차시 교수요목 체계이다."]}, {"p": "414-417", "s": "제3부 3장 범주2 디지털 활용과 창작 수업 사례", "q": "'디지털 활용'(6차시) 교수요목과 평가에 대한 설명으로 옳은 것은?", "o": ["데이터 관리 프로그램 예시로 제시된 구글 코랩은 유료 전용 서비스이다.", "1~2차시는 데이터를 생성·활용하고, 6차시는 과정 소개와 검색·선별을 다룬다.", "'데이터, 정보, 컴퓨팅 시스템의 개념 및 특징'은 응용에 속하므로 지필 고사보다 수행 과정을 평가한다.", "평가는 개념적 부분과 실제 데이터를 다루고 문제를 해결하는 적용 부분이 균형 있게 이루어지도록 한다."], "a": 3, "e": "차시는 검색·선별(1~2) → 구성·관리(3) → 분석·처리(4~5) → 생성·활용(6) 순이다. '개념 및 특징'은 원리에 속해 단답형·선다형으로 평가할 수 있고, 검색~활용은 응용에 속해 전 과정 수행 여부를 평가한다. 구글 코랩은 브라우저에서 파이썬을 작성·실행하는 무료 서비스이다.", "w": ["틀린 설명. 구글 코랩은 무료 서비스이다.", "틀린 설명. 순서가 반대이다. 1~2차시가 소개·검색·선별, 6차시가 생성·활용이다.", "틀린 설명. 개념 및 특징은 '원리'에 속하며 단답형·선다형으로 평가할 수 있다.", "옳은 설명(정답). 개념 평가와 적용 평가의 균형이 필요하다."]}, {"p": "428-430", "s": "제3부 3장 범주2 디지털 활용과 창작 수업 사례", "q": "'미디어 창작' 수업의 교수·학습 목표에 대한 설명으로 옳은 것은?", "o": ["청소년은 교사보다 미디어 활용 능력이 낮으므로 활용 방법 학습에만 집중한다.", "핵심역량은 미디어 기술 역량, 미디어 창의 역량, 미디어 소통 역량이다.", "학습 목표는 콘텐츠 감상과 비평 두 가지로만 구성된다.", "성인 대상 수업에서는 테크놀로지 활용보다 이론 강의를 최우선 과제로 삼는다."], "a": 1, "e": "학습 목표는 ① 미디어 콘텐츠의 구성요소 이해 ② 기획-제작-공유·유통-성찰 과정 이해 ③ 콘텐츠 제작에 직접 참여의 세 가지이다. 성인 대상에서는 테크놀로지 활용을 최우선으로 하며 시범·반복 학습·'휴지(pause)'를 둔다. 청소년은 교사보다 높은 활용 능력을 지닐 수 있어 활용을 넘어 창작에 중점을 둔다.", "w": ["틀린 설명. 청소년은 교사보다 높은 활용 능력을 지닐 수 있어 창작에 중점을 둔다.", "옳은 설명(정답). 표 2-11의 핵심역량이다.", "틀린 설명. 구성요소 이해, 창작 과정 이해, 직접 제작 참여의 세 가지이다.", "틀린 설명. 성인 대상에서는 테크놀로지 활용을 최우선 과제로 삼는다."]}, {"p": "442", "s": "제3부 3장 범주2 디지털 활용과 창작 수업 사례", "q": "미디어 창작을 위한 스토리보드, 콘티, 시놉시스에 대한 설명으로 옳은 것은?", "o": ["시놉시스는 이미지가 포함된 일종의 촬영대본이다.", "콘티는 서사 텍스트에서 작품의 의도와 줄거리를 간략히 서술한 글이다.", "스토리보드는 줄거리와 촬영에 필요한 세부 정보를 시각적으로 정리한 것으로, 편집·마무리 단계에서 체크리스트로도 쓰인다.", "스토리보드는 반드시 정해진 국제 표준 양식에 따라 작성해야 한다."], "a": 2, "e": "교재에서 콘티는 이미지가 없는 일종의 '촬영대본', 시놉시스는 작품의 의도와 줄거리를 간략히 서술한 글로, 둘 다 완결성 있는 스토리보드를 만들기 위한 하위 범주이다. 스토리보드는 구체적인 양식이나 규칙이 정해져 있지 않다.", "w": ["틀린 설명. 촬영대본은 '콘티'이며, 교재는 콘티를 이미지가 없는 것으로 설명한다.", "틀린 설명. 의도와 줄거리를 간략히 서술한 글은 '시놉시스'이다.", "옳은 설명(정답). 스토리보드의 정의와 활용이다.", "틀린 설명. 구체적인 양식이나 규칙이 정해져 있지 않다."]}, {"p": "450-451", "s": "제3부 3장 범주3 미디어 재현과 정보판별 수업 사례", "q": "'미디어 재현' 수업의 교수·학습 목표에 대한 설명으로 옳은 것은?", "o": ["학습 목표는 지식 차원 한 가지로만 제시한다.", "노년기 학습자는 미디어 기술 역량 없이도 미디어 비판 역량을 먼저 갖출 수 있다고 안내한다.", "핵심역량은 미디어 기술 역량과 미디어 비판 역량이다.", "핵심역량은 미디어 창의 역량과 미디어 소통 역량이다."], "a": 2, "e": "미디어 재현 단원은 미디어 기술 역량과 미디어 비판 역량을 핵심적으로 다룬다. 학습 목표는 지식(알아야 할 내용), 기능(정교화할 부분), 태도(내면화할 부분)의 세 차원으로 제시하며, 노년기 학습자에게는 비판 역량을 갖추려면 일정 수준의 기술 역량이 선행되어야 함을 안내한다.", "w": ["틀린 설명. 지식·기능·태도 세 차원으로 나누어 제시한다.", "틀린 설명. 비판 역량을 위해 일정 수준의 기술 역량이 선행되어야 함을 안내한다.", "옳은 설명(정답). 표 3-2의 핵심역량이다.", "틀린 설명. 이는 미디어 창작 단원 핵심역량의 일부이다."]}, {"p": "455-457", "s": "제3부 3장 범주3 미디어 재현과 정보판별 수업 사례", "q": "'미디어 재현' 수업의 평가에 대한 설명으로 옳지 않은 것은?", "o": ["평가 준거가 3가지라면 세부 활동도 3가지로 제시해 각 준거가 문항에 대응되도록 하는 것이 효과적이다.", "시각장애 학습자에게 화면을 해설할 때 교사가 평가적 용어를 사용해 장면의 의미를 먼저 판단해 주는 것이 바람직하다.", "평가 목표는 '미디어 재현의 주체를 고려하여 미디어를 비판적으로 수용하고 미디어의 관점과 의도를 분석한다'처럼 학습자의 구체적 수행과 관련지어 서술한다.", "미디어 비평의 인지적 영역은 정보의 진실성을, 심미적 영역은 예술적 요소를 분석하는 것이다."], "a": 1, "e": "화면의 시각 자료를 해설할 때 교사가 임의로 평가적 용어를 사용하지 않도록 유의한다. 어떤 장면이 나오는지 해설하고 비판적 분석은 학습자가 능동적으로 하도록 이끈다. 비평 영역: 인지적(진실성), 감성적(관련된 사람들의 감정), 심미적(예술적 요소), 도덕적(윤리적 책임감).", "w": ["맞는 설명. 하나의 준거에 한 문항이 대응되도록 설계한다.", "틀린 설명(정답). 교사가 평가적 용어로 설명하지 않고 분석은 학습자에게 맡긴다.", "맞는 설명. 평가 목표 서술 방법이다.", "맞는 설명. 미디어 비평의 영역 구분이다."]}, {"p": "463", "s": "제3부 3장 범주3 미디어 재현과 정보판별 수업 사례", "q": "'정보판별과 확증편향' 수업의 핵심역량에 대한 설명으로 옳은 것은?", "o": ["유아동 학습자는 미디어 시민으로서 주체적 역할을 충분히 수행할 수 있으므로 심화 역량을 요구한다.", "미디어 기술 역량과 미디어 창의 역량을 핵심으로 다룬다.", "미디어 비판 역량은 학습자가 지녀야 할 태도와, 미디어 시민 역량은 학습자의 수행과 직결된다.", "미디어 비판 역량은 학습자의 수행과 직결되고, 미디어 시민 역량은 학습자가 지녀야 할 태도와 관련된다."], "a": 3, "e": "이 단원은 미디어 비판 역량(수행)과 미디어 시민 역량(태도)을 다룬다. 유아동은 초보적 역량으로 미디어 시민의 태도를 함양하는 데 초점을 두고, 노년기는 기술 역량이 선행되어야 함을 안내한다.", "w": ["틀린 설명. 유아동은 주체적 역할 수행이 어려워 초보적 역량에 초점을 둔다.", "틀린 설명. 핵심역량은 미디어 비판 역량과 미디어 시민 역량이다.", "틀린 설명. 설명이 서로 바뀌었다.", "옳은 설명(정답). 비판 역량=수행, 시민 역량=태도이다."]}, {"p": "481-483", "s": "제3부 3장 범주4 미디어 산업과 책임 수업 사례", "q": "'미디어 산업과 소비자' 수업 사례에 대한 설명으로 옳지 않은 것은?", "o": ["핵심역량은 미디어 비판 역량과 미디어 시민 역량이다.", "아동·초등학생은 유튜브·틱톡 등 자주 쓰는 플랫폼의 광고를 대상으로 소비자로서의 가치관 확립 토대를 마련한다.", "노년 학습자는 여전히 활발한 사회 구성원이므로 미디어 산업과 비즈니스, 소비자를 중점적으로 다루는 것이 효율적이다.", "초등학생 대상 수업은 '미디어 산업'에 관한 교육과정 성취기준에 근거해 반드시 지필 평가로만 진행한다."], "a": 3, "e": "교재는 초등학생의 경우 관련 교육과정 성취기준은 없지만, 이미 유튜브·틱톡의 주요 사용자이므로 광고를 무작정 수용하지 않고 비판적으로 인식할 필요가 있다고 설명한다(인지적 방어 능력이 미약한 어린이는 광고에 휩쓸리기 쉬움).", "w": ["맞는 설명. 표 4-2의 핵심역량이다.", "맞는 설명. 아동·초등학생 대상 고려 사항이다.", "맞는 설명. 노년 학습자 대상 고려 사항이다.", "틀린 설명(정답). 초등학생은 관련 성취기준이 없지만 광고를 비판적으로 인식할 필요가 있다."]}, {"p": "486-487", "s": "제3부 3장 범주4 미디어 산업과 책임 수업 사례", "q": "'미디어 산업과 소비자' 수업의 평가에 대한 설명으로 옳지 않은 것은?", "o": ["평가 준거 예시에서 '미디어 산업과 비즈니스'와 '미디어 산업과 소비자'에 각각 30점이 배정된다.", "미디어 산업의 개념과 유형·구조·비즈니스·정책 등 지식 내용은 지필 평가 형태가 적절하다.", "미디어 산업과 문화, 소비자의 위치와 역할 등은 논술 및 프로젝트 형태로 평가할 수 있다.", "개념적 부분만 평가하고 실제 광고 자료를 분석해 문제를 해결하는 적용 부분은 평가하지 않는다."], "a": 3, "e": "평가 시 개념적 부분과 실제 영상·광고 자료를 비판적으로 이해하고 규제 방안을 고안하는 등의 적용 부분이 두루 균형 있게 이루어져야 한다. 배점: 개념과 유형 10, 구조 20, 비즈니스 30, 정책 10, 소비자 30.", "w": ["맞는 설명. 두 요소에 각각 30점이 배정된다.", "맞는 설명. 지식 영역은 지필 평가가 적절하다.", "맞는 설명. 적용·태도 영역은 논술·프로젝트로 평가한다.", "틀린 설명(정답). 개념 평가와 적용 평가가 균형 있게 이루어져야 한다."]}, {"p": "498-501", "s": "제3부 3장 범주4 미디어 산업과 책임 수업 사례", "q": "'협력적 소통과 책임 있는 이용'(5차시) 수업 설계에 대한 설명으로 옳지 않은 것은?", "o": ["3차시 협업 수업은 구성주의 학습 이론에 따라 개방형 질문과 다양한 해석이 가능한 문제 상황을 부여한다.", "프레이밍 이론(창문틀 효과)은 어느 창문으로 보느냐에 따라 같은 풍경도 다르게 보인다는 의미로, 소통 공간을 중층적으로 바라보게 하는 데 활용된다.", "사이버 폭력 실태조사에서 청소년기는 가해·피해 비율이 모두 가장 낮아 이 단원은 성인 대상에 가장 적합하다.", "교수요목은 소통과 참여 → 공유 → 협업 → 사이버 폭력 이해와 대응 → 혐오 표현 이해와 대응 순이다."], "a": 2, "e": "교재는 근래 사이버 폭력 실태조사에서 청소년기의 가해·피해 비율이 모두 높게 확인되므로, 이 단원이 주로 청소년기 대상 교수·학습에 적합하며 반복 학습이 필요하다고 설명한다. 2~5차시 내용은 서로 연속선상에서 이루어지도록 구성한다.", "w": ["맞는 설명. 3차시 협업 수업의 방향이다.", "맞는 설명. 프레이밍 이론의 활용이다.", "틀린 설명(정답). 청소년기의 가해·피해 비율이 모두 높아 청소년 대상에 적합하다.", "맞는 설명. 표 4-12의 교수요목 체계이다."]}, {"p": "521-522", "s": "제3부 3장 범주5 미디어 윤리와 안전 수업 사례", "q": "'디지털 안전' 수업에서 학습 대상자별 고려 사항으로 옳지 않은 것은?", "o": ["노년기 학습자는 감각 기관이 젊은 층보다 예민하므로 학습 시간을 줄이고 인원은 많이 구성한다.", "유아는 개인정보 유출 등 안전이 위협받는 상황을 각색한 대화를 연극(예술 체험형 공연)으로 구성하는 놀이 활용 교수·학습을 설계한다.", "초·중·고 학교 교육과정에서는 창의적 체험활동의 일환으로 사이버 폭력 예방, 개인정보, 스마트폰 과의존 예방 교육 등이 이루어진다.", "노년기 학습자는 노인복지관·평생학습시설 등에서 강의법·토의법·협력 학습을 활용하고 노년층이 경험할 수 있는 사례를 활용한다."], "a": 0, "e": "노년은 감각 기관이 감퇴해 젊은 층보다 학습 시간이 더 필요하므로 충분한 학습 시간을 제공하고, 지적 능력·배경·건강·흥미가 다양하므로 인원수를 적게 구성하며 발표 활동 위주로 구성한다. 추상적 설명보다 구체적·실제적 학습으로 일상에 전이되도록 한다.", "w": ["틀린 설명(정답). 노년은 학습 시간이 더 필요하며 인원을 적게 구성한다.", "맞는 설명. 유아 대상 수업 설계 방법이다.", "맞는 설명. 창의적 체험활동과 연계한 설계가 가능하다.", "맞는 설명. 노년기 학습자 대상 설계 방향이다."]}, {"p": "524, 529-530", "s": "제3부 3장 범주5 미디어 윤리와 안전 수업 사례", "q": "'디지털 안전'(6차시) 수업의 교수요목 구성으로 옳은 것은?", "o": ["1차시 키오스크 적응 → 2차시 위험 요소 대응 → 3차시 과의존 실태 → 4차시 중독 주의 → 5~6차시 신기술", "1~6차시 모두 반드시 연속선상에서만 진행해야 하며 독립 차시 구성은 불가능하다.", "1차시 개인정보 → 2차시 프라이버시 → 3차시 디지털 발자국 → 4차시 지적 재산권 → 5~6차시 디지털 범죄 대응", "1차시 디지털 범죄 → 2차시 저작권 → 3차시 개인정보 → 4차시 과의존 → 5~6차시 키오스크"], "a": 2, "e": "'개인정보 유출 이제 그만!', '나의 프라이버시를 지켜줘!', '디지털 발자국을 관리하라!', '지적 재산권을 보호하라!', '디지털 범죄에 대응하라!' 순이다. 연속선상에서 진행해도 되지만 생애주기별로 필요한 내용을 골라 독립 차시로 구성할 수도 있다. 핵심역량은 미디어 기술·소통·윤리·시민 역량이다.", "w": ["오답. 이는 '디지털 문제해결' 단원의 교수요목이다.", "오답. 독립적인 차시 구성으로도 진행할 수 있다.", "정답. 교재의 디지털 안전 6차시 구성이다.", "오답. 교재 구성과 다르다."]}, {"p": "532-534", "s": "제3부 3장 범주5 미디어 윤리와 안전 수업 사례", "q": "'디지털 안전' 수업의 평가에 대한 설명으로 옳지 않은 것은?", "o": ["평가 기준은 기초 개념 설명, 침해 사례 대응 방안 제시, 디지털 범죄 유형별 특징 설명, 유형별 대응 방법 설명의 네 가지이다.", "디지털 범죄 대응 방안을 캠페인 활동으로 진행할 때 홍보 산출물을 제작하는 수행평가를 할 수 있다.", "평가 준거는 상·중·하 척도 없이 정답·오답 두 가지로만 판정한다.", "평가 목표 달성 여부를 채점하기 위해 분석적 채점 기준표(Rubrics)를 작성해 활용한다."], "a": 2, "e": "평가 준거는 3단계 척도인 상·중·하로 구분해 점수를 다르게 설정하고, 학습자에게 기대하는 수행 수준을 구체적 서술식으로 적는다. 양적·질적 요소 달성 여부에 따라 교사의 전문적 판단으로 점수를 부여할 수 있다.", "w": ["맞는 설명. 네 가지 평가 기준이다.", "맞는 설명. 산출물(팸플릿·포스터 등) 평가가 가능하다.", "틀린 설명(정답). 상·중·하 3단계 척도로 구분한다.", "맞는 설명. 분석적 채점 기준표를 활용한다."]}, {"p": "544-547", "s": "제3부 3장 범주5 미디어 윤리와 안전 수업 사례", "q": "'디지털 문제해결'(6차시) 수업의 차시 구성에 대한 설명으로 옳지 않은 것은?", "o": ["3차시(과의존 실태 파악)와 4차시(과의존·중독 주의)는 강한 연계성이 있으므로 연속성 상에서 진행한다.", "1차시와 2차시는 내용 간 연계성이 매우 강하므로 반드시 연속 차시로 진행해야 한다.", "1차시는 키오스크·스마트 자판기 등 새로운 디지털 기기에 적응하는 단계이다.", "5차시에서는 딥페이크 등 신기술 미디어의 장단점을 Plus·Minus·Interesting으로 나누어 토론하는 PMI 토론을 활용할 수 있다."], "a": 1, "e": "1·2차시는 내용 간 강한 연계성이 없어 독립적인 차시 구성도 무방하다. 반면 3·4차시와 5·6차시는 서로 연계되어 있어 연속성 상에서 진행한다. 이 단원은 개념의 암기·이해보다 실생활 사례 탐구 중심으로 구성한다.", "w": ["맞는 설명. 3·4차시는 연속성 상에서 진행한다.", "틀린 설명(정답). 1·2차시는 독립적인 차시 구성으로 무방하다.", "맞는 설명. 1차시 '새로운 디지털 기기에 적응하라!'이다.", "맞는 설명. P.M.I 토론지 예시가 제시된다."]}]}];
